(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0010.js"] = [{"id":"poem-42e5cadf927f501d8580ed8f","title":"次韵欧阳良有高山仰止四首  其一","author":"赵文","dynasty":"宋","verses":["少年场屋心，富贵轻秋毫。","如何此偪仄，晚作空山逃。","世方驰逐好，我独儒书豪。","宁甘往教远，不肯十上劳。","尚持鹍鸡弦，自爱凤尾槽。","纷然凉州曲，谁赏鬰轮袍。","取之众弃中，君眼亦已高。","惜哉君更穷，相看两萧骚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e5905ffb-3b91-49de-bf82-526671489cf7","tags":[]},{"id":"poem-42f232dcb39498ad67a7619b","title":"又一首","author":"张𬸦","dynasty":"唐","verses":["旧来心使眼，心思眼剩（《唐人小说》本作即。","）传。","由心使眼见，眼亦共心怜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-53e6130a-bb17-41e2-83ef-443a099a79c5","tags":[]},{"id":"poem-42fa3fce550e589dd24c88ed","title":"好事近·春色遍天涯","author":"赵鼎","dynasty":"宋","verses":["春色遍天涯，寒谷未知消息。","且共一尊芳酒，看东风飞雪。","太平遗老洞霄翁，相对两华发。","一任醉魂飞去，访琼瑶宫阙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-968","tags":[]},{"id":"poem-42fe28cb79f02caa56876f68","title":"送刘逖赴闽辟","author":"贯休","dynasty":"唐","verses":["离乱生涯尽，依刘是见机。","从来吟太苦，不得力还稀。","路入闽山熟，江浮瘴雨肥。","何须折杨柳，相送已依依。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-316bb760-a73a-4ae5-a498-a604d2526270","tags":[]},{"id":"poem-4310e4fc7cc0105ed988392d","title":"渔家傲·春恨不禁听杜宇","author":"史浩","dynasty":"宋","verses":["春恨不禁听杜宇。","买舟忽觅东鄞路。","一笑轻帆同野渡。","频回顾。","吴山夜岫俱眉妩。","何事匆匆分袂去。","夫君小隐临烟渚。","明夜月华来竹坞。","相思处。","还应梦属清江橹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-109","tags":[]},{"id":"poem-4312170dbad719ddf4bac44e","title":"兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十二","author":"易静","dynasty":"唐","verses":["风不起，旗号自飞扬。","前指敌军幷阵次，必当我胜用心肠，得胜早回乡。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-bc205dc8-d6a1-447c-8a75-ede3aa0a308d","tags":[]},{"id":"poem-431343e77b7915a8b735ac75","title":"游襄阳山寺","author":"张籍","dynasty":"唐","verses":["秋色江边路，烟霞若有期。","寺贫无利施，僧老足慈悲。","薜荔侵禅窟，虾蟆占浴池。","闲游殊未徧，即是下山时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0a74a799-c767-440f-82d1-182b33e3ddb1","tags":[]},{"id":"poem-431c3d3a249b07d3bbaf4c74","title":"九思·遭厄","author":"王逸","dynasty":"汉","verses":["悼屈子兮遭厄，沉王躬兮湘汨。","何楚国兮难化，迄于今兮不易。","士莫志兮羔裘，竞佞谀兮谗阋。","指正义兮为曲，訿玉璧兮为石。","殦雕游兮华屋，鵔鸃栖兮柴蔟。","起奋迅兮奔走，违群小兮謑訽。","载青云兮上升，适昭明兮所处。","蹑天衢兮长驱，踵九阳兮戏荡。","越云汉兮南济，秣余马兮河鼓。","云霓纷兮晻翳，参辰回兮颠倒。","逢流星兮问路，顾我指兮从左。","俓娵觜兮直驰，御者迷兮失轨。","遂踢达兮邪造，与日月兮殊道。","志阏绝兮安如，哀所求兮不耦。","攀天阶兮下视，见鄢郢兮旧宇。","意逍遥兮欲归，众秽盛兮沓沓。","思哽饐兮诘诎，涕流澜兮如雨。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-60","tags":[]},{"id":"poem-431c6d5c126b821d4fd36775","title":"秋夜自泸溪泛舟入泽泺二首  其一","author":"刘跂","dynasty":"宋","verses":["浮舟入浩渺，有楫任逶迟。","望迷烟树合，影回星汉移。","清静水月界，身到始应知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-6d7733eb-dc8f-490d-9c16-061244889387","tags":[]},{"id":"poem-432070753074427867cbc2ea","title":"杂曲歌辞 长相思三首 一","author":"李白","dynasty":"唐","verses":["长相思，在长安，络纬秋啼金井栏。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有绿水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d4baf2d1-ea61-4fb3-a284-e889275bdca2","tags":["思念","杂曲歌辞","唐诗三百首","乐府","伤怀"]},{"id":"poem-43209eae6761eebd79c463b5","title":"严山人饷蒲萄浆","author":"释居简","dynasty":"宋","verses":["翠朵搴藤剪绿垂，小槽新压水晶澌。","凉州亦有杨州鹤，惆怅山人只要诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-de57fb4a-2914-4f37-aea8-699629999399","tags":[]},{"id":"poem-4322f9ff8085e44c76dfaac1","title":"六州歌头·东风著意","author":"韩元吉","dynasty":"宋","verses":["东风著意。","先上小桃枝。","红粉腻。","娇如醉。","倚朱扉。","记年时。","隐映新妆，面临水岸。","春将半。","云日暖。","斜桥转。","夹城西。","草软莎平跋马，垂杨渡、玉勒争嘶。","认蛾眉凝笑，脸薄拂燕支。","绣户曾窥。","恨依依。","共携手处。","香如雾。","红随步。","怨春迟。","消瘦损。","凭谁问。","只花知。","泪空垂。","旧日堂前燕，和烟雨，又双飞。","人自老。","春长好。","梦佳期。","前度刘郎，几许风流地，花也应悲。","但茫茫暮霭，目断武陵溪。","往事难追。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-58","tags":["宋词三百首"]},{"id":"poem-4324a40b8593aad5d8b5db28","title":"郊庙歌辞 享文敬太子庙乐章 请神","author":"许孟容","dynasty":"唐","verses":["觞牢具品，管磬有节。","祝道夤恭，神仪昭晰。","桐圭早贵，象辂追设。","声达乐成，降歆丰洁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-cc49c7e9-6335-48b7-bef3-6302b96ca84c","tags":[]},{"id":"poem-4326b5bfa79f01a606f9ef91","title":"李三朝奉哀词","author":"王柏","dynasty":"宋","verses":["羌与公别兮几二十年，思渺渺兮路曼曼。","棹剡溪兮乘兴，访故迹兮怆然。","下晋齐之拜兮如梦，挑灯道旧兮犹平生欢。","我少公兮六岁，悼彼此兮华颠。","解予佩兮授予馆，言未终兮岁已阑。","会公疾兮孔炽，怛医穷兮技殚。","闻易箦兮数语，意穆穆兮词严。","湛神爽兮不变，验学力兮深坚。","自磐川与玉局兮，交一世之名贤。","宜公之好修兮，羞芳蕙而糗荃兰。","退静处而莫我知兮，老冉冉其流连。","厌尘世之𫐖轕兮，倏昭明而遂仙。","幸与公兮永诀，抚往事兮自怜。","言告言归兮迈迈，有怀渭水兮渊渊。","栖迟故隠兮，全纯愚而孤处。","当岁莫之急景兮，闻公窀穸之有端。","皎皎兮懿行，卓卓兮瑶镌。","函泳以适意兮，凤冈樵隠之遗稿。","纂记以广业兮，春秋族系之巨编。","岂待是而不朽，掩既往之孤搴。","兰风之臯兮望不极，歌薤露兮有泪悬泉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9407ebd4-81b7-4f9d-91cf-201ef480f6e2","tags":[]},{"id":"poem-432944b37e195fdccdf43456","title":"府试水始冰","author":"马戴","dynasty":"唐","verses":["南池寒色动，北陆岁阴生。","薄薄流澌聚，漓漓翠潋平。","暗沾霜稍厚，回照日还轻。","乳窦悬残滴，湘流减恨声。","即堪金井贮，会映玉壶清。","洁白心虽识，空期饮此明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a7ae6b9f-7099-436e-be20-5f4138618b06","tags":[]},{"id":"poem-43294854cc536bb20bb2a250","title":"临安长官赵两山约观将军木石镜玲珑水浄土寺  其三","author":"释居简","dynasty":"宋","verses":["断崖飞磴徧题名，刻尽玲珑老石英。","欲写苔痕酬胜践，偶然天籁不曾鸣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8457e0f5-a4d8-4179-9290-3f1e066458a7","tags":[]},{"id":"poem-432d6577cb08fccda34bd961","title":"山坡羊","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["儿，你不念我年华高迈，不念我形衰力败，不念我无人养老，不念我绝宗枝派。","我想这桩事不是别人，都足你老祸胎，受了孙家婚聘财，逼得他衔冤负屈投江海。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8229","tags":[]},{"id":"poem-4332c0b007cd49f9c7cd9660","title":"赠童尼","author":"刘言史","dynasty":"唐","verses":["旧时艳质如明玉，今日空心是冷灰。","料得襄王惆怅极，更无云雨到阳台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e6dc08a7-68bb-4817-a92f-48c2bc8657a6","tags":[]},{"id":"poem-4333b706f1e3c46ada70886b","title":"罗浮山下书逸人壁","author":"曹松","dynasty":"唐","verses":["海上亭台山下烟，买时幽邃不争钱。","莫言白日催华发，自有丹砂驻少年。","渔钓未归深竹里，琴壶犹恋落花边。","可中更践无人境，知是罗浮第几天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ad43450a-e60d-4c45-8329-a5901ea0b063","tags":[]},{"id":"poem-434c55199a36c18909c5c692","title":"春夜家宴","author":"王镃","dynasty":"宋","verses":["烛底裁词按玉箫，翠宫合唱取腔娇。","梨花影护春风暖，不用香薰酒自消。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8b46a33b-464d-4ab9-b6dd-861638110467","tags":[]},{"id":"poem-434cfbee3b6daab5a9eab563","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(旦，丑上)前日已预名，届此良辰来殿庭。","拈香炷宝鼎，望慈悲作证盟。","(净)惟愿亡灵来受领，献取香花酒果饼。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8333","tags":[]},{"id":"poem-434d9c5638b93acefc625cfb","title":"归国遥·春欲暮","author":"韦庄","dynasty":"五代","verses":["春欲暮，满地落花红带雨。","惆怅玉笼鹦鹉，单栖无伴侣。","南望去程何许，问花花不语。","早晚得同归去，恨无双翠羽。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-38","tags":[]},{"id":"poem-434dc70e59e8fe2dd4851f7b","title":"秋日送河北从事","author":"裴说","dynasty":"唐","verses":["北风沙漠地，吾子远从军。","官路虽非远，诗名要且闻。","蝉悲欲落日，雕下拟阴云。","此去难相恋，前山掺袂分。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8a7f41d9-d8e2-40d4-8757-79c19029a616","tags":[]},{"id":"poem-4358d12e8ec8f25aae2e0659","title":"坐睡","author":"赵文","dynasty":"宋","verses":["非痴非梦小瞢腾，瞑坐还同入定僧。","口似汝阳狂见曲，头疑季子困悬绳。","儿来问字几三退，客苦多言彊一应。","日日如期不相贷，世情谁似尔堪凭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4f497ca4-bcd1-463e-aab6-01f60677bfd0","tags":[]},{"id":"poem-4364ab104034f5645c989c96","title":"一○三","author":"王梵志","dynasty":"唐","verses":["世无百年人，强作千年调。","（《分门古今类事》卷三引《南史》引此诗，「强」作「拟」，「年」作「岁」，「打」作「以」，「限」作「关」。","）打铁作门限，鬼见拍手笑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-88c2de9f-080c-4132-ae80-ae67c4cf2cf8","tags":[]},{"id":"poem-4368424dac7638ae883f9610","title":"玉楼春·压玉为浆麟作朒","author":"毛滂","dynasty":"宋","verses":["压玉为浆麟作朒。","珠树琼葩长不谢。","翠帘绣暖燕归来，宝鸭花香蜂上下。","沙堤佩马催公驾。","月白风清天不夜。","重来赫赫照岩廊，不动堂堂凝太华。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-793","tags":[]},{"id":"poem-437506bf85139cae0b52194c","title":"江行无题一百首 三十六","author":"钱珝","dynasty":"唐","verses":["水天凉夜月，不是少清光。","好景随人物，秦淮忆建康。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ad835cb8-a01c-43ab-b820-c7a093c3468e","tags":[]},{"id":"poem-43771785e8b5206846ee8b13","title":"挽令人  其二","author":"王十朋","dynasty":"宋","verses":["之子有贤叔，鲰生误受知。","恩蒙夫子妻，事类白圭诗。","黄卷悲吟夜，青灯照绩时。","竟孤偕隠愿，徒切悼亡思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-dbc320a2-c79c-49b5-b9cc-08f10b84dad1","tags":[]},{"id":"poem-4377234d18526792f21b3273","title":"大有·戏马台前","author":"潘希白","dynasty":"宋","verses":["戏马台前，采花篱下，问岁华、还是重九。","恰归来、南山翠色依旧。","帘栊昨夜听风雨，都不似、登归时候。","一片宋玉情怀，十分卫郎清瘦。","红萸佩、空对酒。","砧杆动微寒，暗欺罗袖。","秋已无多，早是败荷衰柳。","强整帽檐侧，曾经向、天涯搔首。","几回忆、故国莼鲈，霜前雁后。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-88","tags":["宋词三百首"]},{"id":"poem-437e2373ff102808d7ae9c0b","title":"次曹少蓬梅花韵","author":"释居简","dynasty":"宋","verses":["涧边寻得压残枝，远寄蓬仙换得诗。","闯水花多凝雪重，漱冰香透出山迟。","笑从秘府朱颜索，洁与缁云素幌宜。","簷隙一痕华月堕，伴蟾蜍玉惜贞姿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2a75699e-314b-45da-9838-17d7f30dc09a","tags":[]},{"id":"poem-438ccd37db34af546547161d","title":"乾元中寓居同谷县作歌七首 五","author":"杜甫","dynasty":"唐","verses":["四山多风溪水急，寒雨飒飒枯树湿。","黄蒿古城云不开，白狐跳梁黄狐立。","我生何为在穷谷，中夜起坐万感集。","鸣呼五歌兮歌正长，魂招不来归故乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e93a77e9-6f3f-4f80-ac47-02924d3acfd1","tags":[]},{"id":"poem-438d34ec3101b2c874beeaf7","title":"拟长安春词","author":"皎然","dynasty":"唐","verses":["春信在河源，春风荡妾魂。","春歌杂𫛸鴂，春梦绕轘辕。","春絮愁偏满，春丝闷更繁。","春期不可定，春曲嬾新翻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-965c0cc3-6966-41d7-b599-eb83a6ee328d","tags":[]},{"id":"poem-438fde6eb6dcc855aca2cdb3","title":"钱申伯自海陵避地临汀闻余北归相迓于武平赋诗见意二首  其二","author":"李纲","dynasty":"宋","verses":["我脱鲸波险，君罹寇盗惊。","暌离四寒暑，会遇两蓬萍。","访旧半为鬼，问津多阻兵。","衣冠漂荡极，风雨自鸡鸣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b4648dda-0b67-40c1-99cc-1b6ce40ab971","tags":[]},{"id":"poem-4399cea9aa2a7ccfa6372bf2","title":"病起","author":"来鹄","dynasty":"唐","verses":["春初一卧到秋深，不见红芳与绿阴。","窗下展书难久读，池边扶杖欲闲吟。","藕穿平地生荷叶，笋过东家作竹林。","在舍浑如远乡客，诗僧酒伴镇相寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f9bc20c3-5663-4c2e-bcca-1c8e25820147","tags":[]},{"id":"poem-439ab52ef2ce6c768921421c","title":"寓北山小阁因事偶作","author":"释了惠","dynasty":"宋","verses":["老去将贫买得闲，十层梯下是人间。","忽因送客闻新事，又嘱山童紧著关。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9c369509-b307-460c-87eb-b2e45608af4c","tags":[]},{"id":"poem-43b6c4e2c16f5007290e4da9","title":"江村","author":"杜甫","dynasty":"唐","verses":["清江一曲抱村流，长夏江村事事幽。","自去自来梁上燕，相亲相近水中鸥。","老妻画纸为棋局，稚子敲针作钓钩。","多病所须惟药物，微躯此外更何求。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-江村","tags":[]},{"id":"poem-43bb94df1f97c6b1d75dbbfa","title":"牧马泉","author":"刘言史","dynasty":"唐","verses":["平沙漫漫马悠悠，弓箭闲抛郊水头。","鼠毛衣里取羌笛，吹向秋天眉眼愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-41e7ebc7-76c3-4292-8f3d-4c2bb6fa4c6b","tags":[]},{"id":"poem-43bc2258c37a7926b7b7c3af","title":"踏莎行·细草愁烟","author":"晏殊","dynasty":"宋","verses":["细草愁烟，幽花怯露。","凭阑总是销魂处。","日高深院静无人，时时海燕双飞去。","带缓罗衣，香残蕙炷。","天长不禁迢迢路。","垂杨只解惹春风，何曾系得行人住。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-504","tags":[]},{"id":"poem-43c2f67bbe86d0b3bf78caa0","title":"三字令·春欲尽","author":"欧阳炯","dynasty":"五代","verses":["春欲尽，日迟迟，牡丹时。","罗幌卷，翠帘垂。","彩笺书，红粉泪，两心知。","人不在，燕空归，负佳期。","香烬落，枕函欹。","月分明，花淡薄，惹相思。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-47","tags":[]},{"id":"poem-43cf143a7f6c466b09696c9c","title":"马诗二十三首 六","author":"李贺","dynasty":"唐","verses":["饥卧骨查牙，粗毛刺破花。","鬣焦朱色落，发断锯长麻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9e8e4fea-14d1-41d0-a777-ddaf67da6146","tags":[]},{"id":"poem-43d1858dc543bf99afca3f76","title":"中谷有蓷","author":"佚名","dynasty":"先秦","verses":["中谷有蓷，暵其干矣。有女仳离，慨其叹矣。慨其叹矣，遇人之艰难矣。","中谷有蓷，暵其修矣。有女仳离，条其歗矣。条其歗矣，遇人之不淑矣。","中谷有蓷，暵其湿矣。有女仳离，啜其泣矣。啜其泣矣，何嗟及矣。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-68","tags":[]},{"id":"poem-43d585435c5f4bd85fc82631","title":"元日朝回中夜书情寄南宫二故人","author":"卢纶","dynasty":"唐","verses":["鸣珮随鹓鹭，登堦见冕旒。","无能裨圣代，何事别沧洲。","闲夜贫还醉，浮名老渐羞。","凤城春欲晚，郎吏忆同游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4f637cfe-2766-4d58-925a-fe3e4ae6b864","tags":[]},{"id":"poem-43d8bc8a6ce649e2eef909a4","title":"蓟门行五首 四","author":"高适","dynasty":"唐","verses":["幽州多骑射，结发重横行。","一朝事将军，出入有声名。","纷纷猎秋草，相向角弓鸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9788cd7e-a89d-4061-8f6e-fcb4d46f8e3a","tags":[]},{"id":"poem-43dab55063cbbc6049c9c118","title":"送僧归日本","author":"贯休","dynasty":"唐","verses":["焚香祝海灵，开眼梦中行。","得达即便是，无生可作轻。","流黄山火著，碇石索雷鸣。","想到夷王礼，还为上寺迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-409fb19a-ee56-4158-88a1-d52bd7f9710f","tags":["黄山"]},{"id":"poem-43dda971de703f4c2ec56790","title":"成都曲","author":"张籍","dynasty":"唐","verses":["锦江近西烟水绿，新雨山头荔枝熟。","万里桥边多酒家，游人爱向谁家宿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-651987af-2600-4410-a813-0d0f8ae28b66","tags":["带有地名","写景","地名"]},{"id":"poem-43e6162a139085048ef6cfae","title":"杨柳枝·秋夜香闺思寂寞","author":"顾敻","dynasty":"五代","verses":["秋夜香闺思寂寞，漏迢迢。","鸳帷罗幌麝烟销，烛光摇。","正忆玉郎游荡去，无寻处。","更闻帘外雨萧萧，滴芭蕉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-15","tags":[]},{"id":"poem-43e981ba5f295daa087c3074","title":"和主司王起","author":"孟球","dynasty":"唐","verses":["当年门下化龙成，今日余波进后生。","仙籍共知推丽藻，禁垣同得荐嘉名。","桃蹊早茂夸新萼，菊圃初开耀晚英。","谁料羽毛方出谷，许教齐和九臯鸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-450da1d8-8fdd-473d-ad15-85b7aabfcdb2","tags":[]},{"id":"poem-43f0a6b96aa3a54069f1c193","title":"长安寓居寄赠贾岛","author":"马戴","dynasty":"唐","verses":["岁暮见华发，平生志半空。","孤云不我弃，归隐与谁同。","枉道紫宸谒，妨栽丹桂丛。","何如随野鹿，栖止石岩中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b4c9a9f7-1393-45dd-a112-4e508ca991f1","tags":[]},{"id":"poem-43feca5d78778a7f00434a57","title":"浣溪沙·偏戴花冠白玉簪","author":"张泌","dynasty":"五代","verses":["偏戴花冠白玉簪，睡容新起意沉吟，翠钿金缕镇眉心。","小槛日斜风悄悄，隔帘零落杏花阴，断香轻碧锁愁深。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-34","tags":[]},{"id":"poem-43ffe3d4e32fb292336609f9","title":"谷风","author":"佚名","dynasty":"先秦","verses":["习习谷风，以阴以雨。黾勉同心，不宜有怒。采葑采菲，无以下体？德音莫违，及尔同死。","行道迟迟，中心有违。不远伊迩，薄送我畿。谁谓荼苦，其甘如荠。宴尔新婚，如兄如弟。","泾以渭浊，湜湜其沚。宴尔新婚，不我屑以。毋逝我梁，毋发我笱。我躬不阅，遑恤我后。","就其深矣，方之舟之。就其浅矣，泳之游之。何有何亡，黾勉求之。凡民有丧，匍匐救之。","不我能畜，反以我为仇。既阻我德，贾用不售。昔育恐育鞫，及尔颠覆。既生既育，比予于毒。","我有旨蓄，亦以御冬。宴尔新婚，以我御穷。有洸有溃，既诒我肄。不念昔者，伊余来塈。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-34","tags":[]},{"id":"poem-44006e9c461f1e456285e8a5","title":"金缕曲·姜西溟言别赋此赠之","author":"纳兰性德","dynasty":"清","verses":["谁复留君住。","叹人生、几翻离合，便成迟暮。","最忆西窗同剪烛，却话家山夜雨。","不道只、暂时相聚。","衮衮长江萧萧木，送遥天、白雁哀鸣去。","黄叶下，秋如许。","曰归因甚添愁绪。","料强似、冷烟寒月，栖迟梵宇。","一事伤心君落魄，两鬓飘萧未遇。","有解忆、长安儿女。","裘敝入门空太息，信古来、才命真相负。","身世恨，共谁语？"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-128","tags":[]},{"id":"poem-4428f85db0d3645425dfd2c6","title":"念奴娇·半阴未雨","author":"曹勋","dynasty":"宋","verses":["半阴未雨，洞房深、门掩清润芳晨。","古鼎金炉，烟细细、飞起一缕轻云。","罗绮娇春。","争拢翠袖，笑语惹兰芬。","歌筵初罢，最宜斗帐黄昏。","楼上念远佳人。","心随沈水，学兰灺俱焚。","事与人非，争似此、些子香气常存。","记得临分。","罗巾馀赠，尽日把浓熏。","一回开看，一回肠断重闻。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-190","tags":[]},{"id":"poem-442ab150bd48eb162a46e318","title":"句","author":"释可勋","dynasty":"宋","verses":["天晓不干钟鼓事，月明岂为夜行人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-66fbb146-a9ad-4665-8b46-7e93692888c1","tags":[]},{"id":"poem-442f8c26c698be809dc04790","title":"姑熟杂咏 慈姥竹","author":"李赤","dynasty":"唐","verses":["野竹攒石生，含烟映江岛。","翠色落波深，虚声带寒早。","龙吟曾未听，凤曲吹应好。","不学蒲柳凋，贞心常自保。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ce3d2a74-0d46-41ac-9d58-ad95c18e0da4","tags":[]},{"id":"poem-44302b3b3f9027a2ffb219ca","title":"掩关铭","author":"卢仝","dynasty":"唐","verses":["蛇毒毒有形，药毒毒有名。","人毒毒在心，对面如弟兄。","美言不可听，深于千丈坑。","不如掩关坐，幽鸟时一声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1d1553c3-e3fc-4073-9512-1e6b16f06046","tags":[]},{"id":"poem-4432494144d3f39cfd86ca45","title":"生查子·当初相见时","author":"张先","dynasty":"宋","verses":["当初相见时，彼此心萧洒。","近日见人来，却恁相谩諕。","休休休便休，美底教他且。","匹似没伊时，更不思量也。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-308","tags":[]},{"id":"poem-4434fcdbd4041431db25f8bb","title":"浣溪沙·蓼岸风多枯柚香","author":"孙光宪","dynasty":"五代","verses":["蓼岸风多枯柚香，江边一望楚天长，片帆烟际闪孤光。","目送征鸿飞杳杳，思随流水去茫茫，兰红波碧忆潇湘。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-37","tags":[]},{"id":"poem-44424804db79f85d40787266","title":"饯唐永昌","author":"徐坚","dynasty":"唐","verses":["郎官出宰赴伊瀍，征传骎骎灞水前。","此时怅望新丰道，握手相看共黯然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5a9c7cf3-39a4-48f7-8636-27915ed0004e","tags":[]},{"id":"poem-444536e3f4d43aac747364c6","title":"叹昨日三首 三","author":"卢仝","dynasty":"唐","verses":["上帝板板主何物，日车劫劫西向没。","自古贤圣无奈何，道行不得皆白骨。","白骨土化鬼入泉，生人莫负平生年。","何时出得禁酒国，满瓮酿酒曝背眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-27e447ee-3210-40f1-8e5a-299cda7ccc9b","tags":[]},{"id":"poem-444ccf2b15faec6df5eaec6e","title":"赠晦公禅人","author":"贯休","dynasty":"唐","verses":["流阳为役者，相访叶纷纷。","有句虽如我，无心未似君。","搆林青及竹，茆屋暖于云。","何日相将去，千山麋鹿群。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4fbc473c-0e44-4473-a652-e2d492942c4c","tags":[]},{"id":"poem-44503b9ab34239d57bd58a07","title":"黄鹤楼送孟浩然之广陵","author":"李白","dynasty":"唐","verses":["故人西辞黄鹤楼，烟花三月下扬州。","孤帆远影碧山尽，唯见长江天际流。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d43a4767-2240-44b7-8d5b-c2acdc689839","tags":["唐诗三百首","长江","黄鹤楼","离别","带有地名","小学古诗","地名","描写水","友情","写景","送别","七言绝句"]},{"id":"poem-4450c0ca3ed58406538c5915","title":"夜游","author":"沈佺期","dynasty":"唐","verses":["今夕重门启，游春得夜芳。","月华连昼色，灯影杂星光。","南陌青丝骑，东邻红粉妆。","管弦遥辨曲，罗绮暗闻香。","人拥行歌路，车攒鬬舞场。","经过犹未已，钟鼓出长杨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-3eaef5d7-9118-435a-ac36-e26540edbcf2","tags":[]},{"id":"poem-445d870bedc030f229110918","title":"奉和七夕两仪殿会宴应制","author":"赵彦昭","dynasty":"唐","verses":["青女三秋节，黄姑七日期。","星桥度玉珮，云阁掩罗帷。","河气通仙掖，天文入睿词。","今宵望灵汉，应得见蛾眉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-357a9b75-35fa-4e0c-9a10-1d51f84a1e6f","tags":[]},{"id":"poem-447a4220f8b4f2885e3a883e","title":"送方外上人","author":"刘长卿","dynasty":"唐","verses":["孤云将野鹤，岂向人间住。","莫买沃洲山，时人已知处。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c26445b5-a433-4cd7-9020-435866b845f9","tags":["唐诗三百首","送别","五言绝句"]},{"id":"poem-447a63fa06e6cb686ee40a00","title":"赵左厢再荐","author":"释居简","dynasty":"宋","verses":["勤苦佐丰年，成功只听天。","聊挥数寸管，不费一文钱。","灯娄层葩剪，杨曾百步穿。","宗藩大廷对，可惜两名先。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-f1776b6e-a47b-4f13-82ad-9abc77cf62e2","tags":[]},{"id":"poem-447af2d076b3dc5a24d8ef20","title":"太平歌","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["他求科举，指望锦衣归，不想道你留他为女婿。","(外)有缘千里能相会，须强他不得，。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5175","tags":[]},{"id":"poem-447d2cfe3ca385ce416a62de","title":"梁太子钓台","author":"释居简","dynasty":"宋","verses":["晴拂双鬟晓未开，先驱寸碧渡江来。","伤心旧日垂纶地，几度江春去又回。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-f47a83c0-614e-495b-97a0-6b7d92b98e3f","tags":[]},{"id":"poem-44803d9660fabaf6bf1277a3","title":"杂诗四首  其二","author":"李涛","dynasty":"宋","verses":["燕雀贺厦屋，虫蚁慕腥膻。","野花引飞蝶，古木来新蝉。","秋天百虫吟，春天百鸟喧。","翟公真暗事，喜愠见色言。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-95b636a2-edce-41a2-a3e7-ef599ad64ba1","tags":[]},{"id":"poem-44848eaf097290c500967e1a","title":"白头吟","author":"张籍","dynasty":"唐","verses":["请君漆上琴，弹我白头吟。","忆昔君前娇笑语，两情宛转如萦素。","宫中为我起高楼，更开花池种芳树。","春天百草秋始衰，弃我不待白头时。","罗襦玉珥色未暗，今朝已道不相宜。","扬州青铜作明镜，暗中持照不见影。","人心回互自无穷，眼前好恶那能定。","君恩已去若再返，菖蒲花开月长满。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fef3b512-d4e0-473b-9b3a-b1d87831dfdd","tags":[]},{"id":"poem-448ecd730acaef3c0776ff34","title":"柳枝·腻粉琼妆透碧纱","author":"张泌","dynasty":"五代","verses":["腻粉琼妆透碧纱，雪休夸。","金凤搔头堕鬓斜，发交加。","倚着云屏新睡觉，思梦笑。","红腮隐出枕函花，有些些。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-46","tags":[]},{"id":"poem-44ad1908af6a90053abaa0e7","title":"酒泉子·掩却菱花","author":"顾敻","dynasty":"五代","verses":["掩却菱花，收拾翠钿休上面。","金虫玉燕锁香奁，恨厌厌。","云鬟半坠懒重簪，泪侵山枕湿。","恨灯背帐梦方酣，雁飞南。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-12","tags":[]},{"id":"poem-44b95d7b22f1903e2c630529","title":"送马向入蜀","author":"徐凝","dynasty":"唐","verses":["游子出咸京，巴山万里程。","白云连鸟道，青壁遰猨声。","雨雪经泥坂，烟花望锦城。","工文人共许，应纪蜀中行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-79e46a04-dba5-4ecb-952f-416ed2cd527c","tags":[]},{"id":"poem-44bfb0c0384f3d6fee1ef07e","title":"荅太原从军杨员外送别","author":"马戴","dynasty":"唐","verses":["君将海月珮，赠之光我行。","见知言不浅，怀报意非轻。","反照临歧思，中年未达情。","河梁人送别，秋汉鴈相鸣。","衰柳摇边吹，寒云冒古城。","西游还献赋，应许托平生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-79b4e2e7-8425-45ce-9f77-0e9673355628","tags":[]},{"id":"poem-44c75cfe","title":"竹石","author":"郑燮","dynasty":"清","verses":["咬定青山不放松，立根原在破岩中。","千磨万击还坚劲，任尔东西南北风。"],"enabled":true,"collection":"历代名篇","source":"郑燮《板桥诗钞》题画诗《竹石》。","tags":["咏物","竹","言志"]},{"id":"poem-44ca2191f0e3cd2e2d1cbcec","title":"玉楼春·去时梅萼初凝粉","author":"欧阳修","dynasty":"宋","verses":["去时梅萼初凝粉。","不觉小桃风力损。","梨花最晚又凋零，何事归期无定准。","阑干倚遍重来凭。","泪粉偷将红袖印。","蜘蛛喜鹊误人多，似此无凭安足信。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-687","tags":[]},{"id":"poem-44cbb8d6a49027d1b8964228","title":"寓怀","author":"李山甫","dynasty":"唐","verses":["万古交驰一片尘，思量名利孰如身。","长疑好事皆虚事，却恐闲人是贵人。","老逐少来终不放，辱随荣后直须匀。","劝君不用夸头角，梦里输赢总未真。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-481de596-c60e-45d1-99d8-b715f46d5bb7","tags":[]},{"id":"poem-44d203f4b87d9f0e63d3d4e1","title":"青衫湿·悼亡","author":"纳兰性德","dynasty":"清","verses":["近来无限伤心事，谁与话长更。","从教分付，绿窗红泪，早雁初莺。","当时领略，而今断送，总负多情。","忽疑君到，漆灯风飐，痴数春星。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-16","tags":[]},{"id":"poem-44d8163e629897cc26277eeb","title":"青玉案·红尘冉冉长安路","author":"张孝祥","dynasty":"宋","verses":["红尘冉冉长安路。","看风度、凝然去。","唱彻阳关留不住。","甘棠庭院，芰荷香渚。","尽是相思处。","龟鱼从此谁为主。","好记江湖断肠句。","万斛离愁休更诉。","洞庭烟棹，楚楼风露。","去作为霖雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-225","tags":["洞庭湖"]},{"id":"poem-44f5032ba484aae3ec802d61","title":"奉和幸上官昭容院献诗四首 一","author":"郑愔","dynasty":"唐","verses":["地轴楼居远，天台阙路赊。","何如游帝宅，即此对仙家。","座拂金壶电，池摇玉酒霞。","无云秦汉隔，别访武陵花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-877fdbe6-1d4f-42ef-9106-8237f10420ae","tags":[]},{"id":"poem-44f95f2d3aab9f452a1d9acd","title":"偈颂（幷序○序为南岳齐己撰） 四十三","author":"居遁","dynasty":"唐","verses":["木食草衣心似月，一生无念复无涯。","时人若问居何处，渌水青山是我家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b72b0da6-c480-4edd-9acc-0e3bca21cc8e","tags":["衡山"]},{"id":"poem-44fa1a74d9b0051d49d7dc7e","title":"更漏子·小窗前","author":"向子𬤇","dynasty":"宋","verses":["小窗前，疏影下。","鸾镜弄妆初罢。","梅似雪，雪如人。","都无一点尘。","暮江寒，人响绝。","更着朦胧微月。","山似玉，玉如君。","相看一笑温。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-147","tags":[]},{"id":"poem-44fcf7f846df663070f67c7c","title":"净居主人索诗急笔赋","author":"陈造","dynasty":"宋","verses":["净居栋宇犀辟尘，山居不乏尘外人。","我来肯作厌客想，老语一一刊翠珉。","频年愧烦香积供，醉后狂言亦安用。","诗成每博复瓿讥，更向丛林系轻重。","皎公启公后进师，好事继今谁似之。","他年落笔须妙质，政自两公劳梦思。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b8d46e0c-2488-4460-ab9f-00757650f9f1","tags":[]},{"id":"poem-45082ba3700d61c675ddffb2","title":"早春病中","author":"张籍","dynasty":"唐","verses":["羸病及年初，心情不自如。","多申请假牒，祗送贺官书。","幽径独行步，白头长嬾梳。","更怜晴日色，渐渐暖贫居。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ba68f2e9-87b9-4ba1-84b6-bbe65c46bcd5","tags":[]},{"id":"poem-4514f244412fa813ecb9732d","title":"混江龙","author":"杨景贤","dynasty":"元","verses":["也是我为人不肖，和这等朝三暮四的便成交。","安排着山果，准备着香醪。","一派笙歌尝御酒，抵多少九重春色醉仙桃。","山光明媚，柳色妖娆，莺歌巧韵，燕舞纤腰。","狐变成美丽，虎变作多娇，着我忍不住一场好笑。","执壶的是木客，把酒的是山魈。","(孙行者上，云)我天宫内盗得仙衣、仙帽、仙桃、仙酒，夫人快活受用。","(金女唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10301","tags":[]},{"id":"poem-45178addc5599e244d28e765","title":"眼儿媚·花近清明晚风寒","author":"曾觌","dynasty":"宋","verses":["花近清明晚风寒。","锦幄兽香残。","醺醺醉里，匆匆相见，重听哀弹。","春情入指莺声碎，危柱不胜弦。","十分得意，一场轻梦，淡月阑干。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-368","tags":[]},{"id":"poem-452419d0399191bb2cf08dc4","title":"武陵春·城上落梅风料峭","author":"毛滂","dynasty":"宋","verses":["城上落梅风料峭，寒馥逼清尊。","爽兴天教属使君。","雪意压歌云。","插帽殷罗金缕细，燕燕早随人。","留取笙歌直到明。","莲漏已催春。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-846","tags":[]},{"id":"poem-452a0a2d368af3afaa6d64c2","title":"洋州三十景 涵虚亭","author":"鲜于侁","dynasty":"宋","verses":["危栏试睡听，空翠如何把。","悄悄忧世心，临风一倾泻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8eaeef5b-789b-4ef3-91c5-5534cea8fc74","tags":[]},{"id":"poem-45307dcab41b495baf17cd67","title":"长信宫","author":"刘得仁","dynasty":"唐","verses":["簟凉秋气初，长信恨何如。","拂黛月生指，解鬟云满梳。","一从悲画扇，几度泣前鱼。","坐听南宫乐，清风摇翠裾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-50397bb4-b68f-43a0-bc2c-b7cfa36f50da","tags":[]},{"id":"poem-4530867312064937bfb3b5c9","title":"送惟良上人归润州","author":"李端","dynasty":"唐","verses":["拟诗偏不类，又送上人归。","寄世同高鹤，寻仙称坏衣。","雨行江草短，露坐海帆稀。","正被空门缚，临岐乞解围。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c9d73415-8fff-4c3a-8857-f49b49e3fdf1","tags":[]},{"id":"poem-45329788c847d9c5d61ae6b8","title":"宫词","author":"薛逢","dynasty":"唐","verses":["十二楼中尽晓妆，望仙楼上望君王。","锁衔金兽连环冷，水滴铜龙昼漏长。","云髻罢梳还对镜，罗衣欲换更添香。","遥窥正殿帘开处，袍袴宫人扫御床。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f8d102c4-b25b-412f-afce-35db35c339d9","tags":["唐诗三百首","宫怨","七言律诗"]},{"id":"poem-45356be44e45835c348e7227","title":"早朝大明宫","author":"贾至","dynasty":"唐","verses":["银烛朝天紫陌长，禁城春色晓苍苍。","千条弱柳垂青锁，百啭流莺绕建章。","剑佩声随玉墀步，衣冠身惹御炉香。","共沐恩波凤池上，朝朝染翰侍君王。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-早朝大明宮","tags":[]},{"id":"poem-4541d8ffb5361449e43660b0","title":"渔父","author":"史卫卿","dynasty":"宋","verses":["白头长是醉，湖海不知年。","活业惟耕纲，全家衹住船。","荷花同鹭宿，杨柳得鱼穿。","一笛吹明月，朱门谩管弦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4f36782e-4b43-40f9-a1de-5ef2b91d6ed8","tags":[]},{"id":"poem-45429e78d6352fe76027677b","title":"谒大慈恩寺","author":"高宗皇帝","dynasty":"唐","verses":["日宫开万仞，月殿耸千寻。","花盖飞团影，幡虹曳曲阴。","绮霞遥笼帐，丛珠细网林。","寥廓烟云表，超然物外心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7a91f55d-4f60-45b4-b9e2-36ddfd8ac342","tags":[]},{"id":"poem-454725a3c0fb131156cd2a21","title":"题泾县水西寺","author":"宣宗皇帝","dynasty":"唐","verses":["大殿连云接爽溪，钟声还与鼓声齐。","长安若问江南事，说道风光在水西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9abf192a-34e2-410d-addc-68171f00c3f0","tags":[]},{"id":"poem-454da23de613c92bb8e3779c","title":"题梅仙馆","author":"孟宾于","dynasty":"宋","verses":["仙界路遥云缥缈，古坛风冷叶萧骚。","后来岂合言淹滞，一尉升腾道最高。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d22c4244-85a2-4278-9db9-b278f7558f48","tags":[]},{"id":"poem-455500bbcfcd831e9342bb8b","title":"句 三","author":"李煜","dynasty":"五代","verses":["玉俎且共甘，羽觞合同嘉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e6f94d84-0fdb-4af2-b439-02ec2d70bd97","tags":[]},{"id":"poem-455d0469032b52d8f802d4ed","title":"夜闻江南人家赛神因题即事","author":"李嘉祐","dynasty":"唐","verses":["南方淫祀古风俗，楚妪解唱迎神曲。","鎗鎗铜鼓芦叶深，寂寂琼筵江水绿。","雨过风清洲渚闲，椒浆醉尽迎神还。","帝女凌空下湘岸，番君隔浦向尧山。","月隐回塘犹自舞，一门依倚神之祜。","韩康灵药不复求，扁鹊医方曾莫覩。","逐客临江空自悲，月明流水无已时。","听此迎神送神曲，携觞欲吊屈原祠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7e30c468-9d80-4b8c-9a87-1276b583687a","tags":[]},{"id":"poem-456eea0f99ee943b4205ea16","title":"失调名·手把合欢彩索","author":"张耒","dynasty":"宋","verses":["手把合欢彩索，殷勤微笑𣨼檀郎。","低低告，不图系腕，图系人肠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-354","tags":[]},{"id":"poem-457838f045dc08114a146f57","title":"送知宗奉祠还越  其一","author":"王十朋","dynasty":"宋","verses":["堂堂人物宋宗英，来主金枝玉叶盟。","麟趾化成公族厚，棣华诗作争心平。","金尊对客吟篇逸，贝叶谈空世味轻。","五月仙舟鉴湖去，芰荷香里奏新声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-5a2cadc2-9d3d-4259-a7fb-7864ab14050a","tags":[]},{"id":"poem-4580d1e0cf641f9bc82b4a92","title":"宫词  其八","author":"张公庠","dynasty":"宋","verses":["晨光初动阁门开，百辟匆匆避路回。","千步画廊敲杖子，朱衣双引相公来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-919bc965-3409-4063-bbb9-8c6f4a600b87","tags":[]},{"id":"poem-45843cd5b533f4a067d8c682","title":"秦镜","author":"独孤绶","dynasty":"唐","verses":["万古秦时镜，从来抱至精。","依台月自吐，在匣水常清。","烂烂金光发，澄澄物象生。","云天皆洞鉴，表里尽虚明。","但见人窥胆，全胜响应声。","妍媸定可识，何处更逃情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-41960329-86d2-4636-83cf-80292b6d1bb9","tags":[]},{"id":"poem-45888b4d6edbb5645c80667d","title":"寓兴","author":"宋伯仁","dynasty":"宋","verses":["又近重阳节，伤心事可嗟。","塞鸿河洛志，篱菊古今花。","苦雨床俱漏，颠风扇莫遮。","渔船如一叶，快活似侬家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-90c3fd31-f2f6-4357-9f7b-64646f5d39fa","tags":[]},{"id":"poem-458dd03a868e1fbb0b86a1a5","title":"酬贺四赠葛巾之作","author":"王维","dynasty":"唐","verses":["野巾传惠好，兹贶重兼金。","嘉此幽栖物，能齐隐吏心。","早朝方暂挂，晚沐复来簪。","坐觉嚣尘远，思君共入林。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ee7d6f1c-26d6-426e-91dc-5d7bd2189c77","tags":[]},{"id":"poem-4592292f9bde9e87ab130b93","title":"诉衷情·晚妆初试蕊珠宫","author":"曾觌","dynasty":"宋","verses":["晚妆初试蕊珠宫。","随步异香浓。","檀槽缓垂鸾带，纤指拈春葱。","莺语巧，上林中。","正娇慵。","暂教花下，帘影微开，多谢东风。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-365","tags":[]},{"id":"poem-45947e3c726b23dd1a2cb463","title":"锦缠道","author":"无名氏《张协状元》","dynasty":"元","verses":["苦天天，几年来劳笼着万千，寻思自埋冤。","少它张协债负，是奴前缘。","大雪下身无寸缕，投古庙泪珠涟涟。","奴家便相怜，与它身衣口食。","教人说化我，共它成因眷，只图它共百年。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2696","tags":[]},{"id":"poem-4597aa02971016c0a1d901c7","title":"送顾八分文学适洪吉州","author":"杜甫","dynasty":"唐","verses":["中郎石经后，八分盖顦顇。","愿侯运𬬻锤，笔力破余地。","昔在开元中，韩蔡同赑屭。","玄宗妙其书，是以数子至。","御札早流传，揄扬非造次。","三人竝入直，恩泽各不二。","愿于韩蔡内，辨眼工小字。","分日示诸王，钩深法更秘。","文学与我游，萧疎外声利。","追随二十载，浩荡长安醉。","高歌卿相宅，文翰飞省寺。","视我扬马间，白首不相弃。","骅骝入穷巷，必脱黄金辔。","一论朋友难，迟暮敢失坠。","古来事反复，相见横涕泗。","向者玉珂人，谁是青云器。","才尽伤形体，病渴污官位。","故旧独依然，时危话颠踬。","我甘多病老，子负忧世志。","胡为困衣食，颜色少称遂。","远作辛苦行，顺从众多意。","舟檝无根蔕，蛟鼍好为祟。","况兼水贼繁，特戒风飙驶。","崩腾戎马际，往往杀长吏。","子干东诸侯，劝勉防纵恣。","邦以民为本，鱼饥费香饵。","请哀疮痍深，告诉皇华使。","使臣精所择，进德知历试。","恻隐诛求情，固应贤愚异。","列士恶苟得，俊杰思自致。","赠子猛虎行，出效载酸鼻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d2cb0132-c27d-4037-abb6-c76f576b866b","tags":[]},{"id":"poem-45994d38c07b62c5d5f552a7","title":"摊声浣溪沙・浣溪沙·日照门前千万峰","author":"毛滂","dynasty":"宋","verses":["日照门前千万峰。","晴飙先扫冻云空。","谁作素涛翻玉手，小团龙。","定国精明过少壮，次公烦碎本雍容。","听讼阴中苔自绿，舞衣红。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-754","tags":[]},{"id":"poem-459a0bdd92ad6263bc8459ad","title":"捣纸","author":"释居简","dynasty":"宋","verses":["万杵不为轻，丁宁玉汝成。","忽闻敲月响，误作捣衣声。","整整云添薄，方方雪更明。","沉思过秦手，古恨满笺生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-91aae69e-a5d6-45e9-a6ef-4cc24cc16d4c","tags":[]},{"id":"poem-45b202b0faad66d7a77f1d6f","title":"临江仙·幽闺欲曙闻莺啭","author":"毛熙震","dynasty":"五代","verses":["幽闺欲曙闻莺啭，红窗月影微明。","好风频谢落花声，隔帷残烛，犹照绮屏筝。","绣被锦茵眠玉暖，炷香斜袅烟轻。","淡蛾羞敛不胜情，暗思闲梦，何处逐云行。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-41","tags":[]},{"id":"poem-45b36f2620ff46bb3d789929","title":"和邓慎思重九考罢试卷书呈同院诸公二首  其一","author":"李公麟","dynasty":"宋","verses":["吁俊天畿合辟雍，愧将瓦釜缀黄钟。","听穷一一竽无滥，拨遍磷磷玉似逢。","龟列春庭先壤奠，龙飞天路得云从。","吾曹莫念拘萦久，求称公朝庆赏浓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-388df771-1fe4-4e9e-80ae-6d4b4f7e91ca","tags":[]},{"id":"poem-45ba2581ccd7cc91dcf41402","title":"失白鹰","author":"郑繇","dynasty":"唐","verses":["白锦文章乱，丹霄羽翮齐。","云中呼暂下，雪里放还迷。","梁苑惊池鹜，陈仓拂野鸡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-097b2ef7-d98e-4ece-afdf-d271139ec20e","tags":[]},{"id":"poem-45bf58e361f5919cee74375c","title":"山居杂兴  其一","author":"艾可翁","dynasty":"宋","verses":["老夫晨沐罢，还卧看云行。","发短便巾小，衰容怯镜明。","空林存竹意，破屋带泉声。","自喜诗棋外，无营梦亦清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5d95b9a5-30c4-4891-95d8-ad6415e2ede5","tags":[]},{"id":"poem-45c8b37a9db2ee290fd65ca7","title":"经杜工部坟","author":"裴说","dynasty":"唐","verses":["骚人久不出，安得国风清。","拟掘孤坟破，重教大雅生。","皇天高莫问，白酒恨难平。","悒怏寒江上，谁人知此情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8c64fb66-2c36-4866-a2a7-3508dd901c49","tags":[]},{"id":"poem-45d0ecb3794212daaedcf2ac","title":"送薛少卿赴青阳","author":"徐铉","dynasty":"宋","verses":["我爱陶靖节，吏隠从弦歌。","我爱费征君，高卧归九华。","清风激颓波，来者何以加。","我志两不遂，漂沦浩无涯。","数奇时且乱，此图今愈赊。","贤哉薛夫子，高举凌晨霞。","安民即是道，投足皆为家。","功名与权位，悠悠何用夸。","携朋出远郊，酌酒藉平沙。","云收远天静，江阔片帆斜。","离怀与企羡，南望长咨嗟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-297bc7e3-eb9a-45c8-90f9-30011c6944c5","tags":[]},{"id":"poem-45d39bd0c29e344bfbff26eb","title":"同房侍御山园新亭与邢判官同游","author":"高适","dynasty":"唐","verses":["隐隐春城外，朦胧陈迹深。","君子顾榛莽，兴言伤古今。","决河导新流，疏迳踪旧林。","开亭俯川陆，时景宜招寻。","肃穆逢使轩，夤缘事登临。","忝游芝兰室，还对桃李阴。","岸远白波来，气喧黄鸟吟。","因睹歌颂作，始知经济心。","灌坛有遗风，单父多鸣琴。","谁为久州县，苍生怀德音。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f38c1894-0609-4b47-b3d9-48e1b6543efe","tags":[]},{"id":"poem-45e0217d9445f8701461bbb8","title":"齿疾未平灸疮正作新诗又至奇韵难当暗忍呻吟强思酬和别披小简盖念短才更竭病怀甘输降款  其五","author":"李昉","dynasty":"宋","verses":["一簇檀栾爱者多，朝昏赏玩意如何。","北轩小槛方栽植，东观新诗已咏歌。","啼鸟恋枝长懒去，邻僧为尔数来过。","丛边若有东流水，堪看清阴照绿波。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-0963b1c3-9346-4f7c-afd8-efefbd3cb75a","tags":[]},{"id":"poem-45e0d5d3e1f520a129ca6c99","title":"尉迟杯·去年时","author":"晁补之","dynasty":"宋","verses":["去年时。","正愁绝，过却红杏飞。","沈吟杏子青时。","追悔负好花枝。","今年又春到，傍小阑、日日数花期。","花有信，人却无凭，故教芳意迟迟。","及至待得融怡。","未攀条拈蕊，已叹春归。","怎得春如天不老，更教花与月相随。","都将命、拼与酬花，似岘山、落日客犹迷。","尽归路，拍手拦街，笑人沈醉如泥。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-186","tags":[]},{"id":"poem-45e0f04f86ad82245a97f746","title":"次韵申伯上杭道中见示二首  其二","author":"李纲","dynasty":"宋","verses":["相逢闽岭得同行，秋早凄然风露清。","蝉曳残声吟翳荟，泉飞小瀑落峥嵘。","浓云林表千峰立，细路山腰一线横。","坎止川流任天运，未应萍梗叹劳生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-41f53ea1-e549-4aa2-96c7-2795876261e2","tags":[]},{"id":"poem-45e57d16bfbfdf6adbe8fdc8","title":"临江仙·瘦损东阳缘底事","author":"向","dynasty":"宋","verses":["瘦损东阳缘底事，离愁别恨难禁。","夜长谁共拥孤衾。","来时青鬓在，今已二毛侵。","流水青山依旧是，兰桡往事空寻。","一番风雨又春深。","桃花都落尽，赢得是清阴。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-188","tags":[]},{"id":"poem-45f0a2767dbe1eb729c4a03a","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生)上告公公见怜，再告婆婆听言，这恩德铭心镂肝。","若是收留在宅上，大凡事自当向前。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8823","tags":[]},{"id":"poem-45f18678198380e107d0623f","title":"登巾山","author":"陈知柔","dynasty":"宋","verses":["司马胸中著云梦，杜陵眼底盖乾坤。","吾衰不复论兹事，饱看孤帆落远村。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-6e4ae72f-9313-448b-84bf-66b4ed796a4f","tags":[]},{"id":"poem-460b1efaac02d128e7af9698","title":"双山过信公所居","author":"包佶","dynasty":"唐","verses":["遥礼前朝塔，微闻后夜钟。","人间第四祖，云里一双峰。","积雨封苔径，多年亚石松。","传心不传法，谁可继高踪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-4e1e3697-9fad-4ec7-9c4e-4bc4b8bb90f3","tags":[]},{"id":"poem-4611004ca87a568b523d196a","title":"调笑・调笑令·相忆","author":"晁补之","dynasty":"宋","verses":["相忆。","顿轻掷。","春草佳名渐赠璧。","长洲茂苑吴王国。","自有芊绵碧色。","根生土长铜驼陌。","纵欲随君争得。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-285","tags":[]},{"id":"poem-462b51252a2335c53bd30bab","title":"句","author":"李潭","dynasty":"唐","verses":["人过远村秋日晚，鸟飞平野暮天空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-460f31de-51f2-4ff1-8dd7-9d69dbb32e5f","tags":[]},{"id":"poem-462d3cb53fee2af66fe65263","title":"雨夜见投之作","author":"司空曙","dynasty":"唐","verses":["出户繁星尽，池塘暗不开。","动衣凉气度，遰树远声来。","灯外初行电，城隅偶隐雷。","因知谢文学，晓望比尘埃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-71862ef7-dc20-401d-a624-f079b6a089b9","tags":[]},{"id":"poem-463992b8439e5ded28063cf4","title":"寄灵一上人初归云门寺","author":"张籍","dynasty":"唐","verses":["寒山白云里，法侣自招携。","竹径通城下，松门隔水西。","方同沃洲去，不作武陵迷。","髣髴遥看处，秋风是会稽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-35bfb080-c773-4bbe-9fe9-b4f1b30d6e4e","tags":[]},{"id":"poem-463eaa766e9d82bf1f222e57","title":"题曾氏山园十一咏 尚䌹堂","author":"张栻","dynasty":"宋","verses":["昔人为己学，深旨妙隠微。","三复尚䌹章，服膺愿无违。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-aa4c6106-c91a-4023-8f4f-bf8bd44ccaa3","tags":[]},{"id":"poem-4643927d024296e66f061bda","title":"惠州访东坡旧隐","author":"李纲","dynasty":"宋","verses":["海上归来访老坡，依然遗迹未销磨。","松风亭下梅花老，鹤观峰头乔木多。","垂世文章灿星斗，平生忧患足风波。","华堂满龛题诗笔，人事其如天定何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-49c0c62d-a301-4394-9966-1b8e6a941f8c","tags":[]},{"id":"poem-464dec35cd9e717382d3cc5c","title":"游仙窟诗 答文成","author":"崔十娘","dynasty":"唐","verses":["天涯地角知何处，玉体红颜难再遇。","但令翅羽为人生，会些高飞共君去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-52a31a6f-766d-416e-aca8-9cfad2acade3","tags":[]},{"id":"poem-464f3ade53bccdee2d6ee189","title":"诫宗教接物颂","author":"智闲","dynasty":"唐","verses":["三句语，究人玄。","迅面目，示豁然。","开两路，备机缘。","投不遇，说多年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-79b5f82b-0c49-4cdb-915f-90082f71cccc","tags":[]},{"id":"poem-4657fdc643f72b25db05d64f","title":"金陵酒肆留别","author":"李白","dynasty":"唐","verses":["风吹柳花满店香，吴姬压酒唤客尝。","金陵子弟来相送，欲行不行各尽觞。","请君试问东流水，别意与之谁短长。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-809ad73b-9a8e-436e-9874-f9295b624af0","tags":["唐诗三百首","七言古诗","离别","饮酒"]},{"id":"poem-465bd6ea1a47437244c9a80b","title":"送别","author":"杨凭","dynasty":"唐","verses":["江岸梅花雪不如，看君驿驭向南徐。","相闻不必因来雁，云里飞輧落素书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d3848220-b67b-4df1-87ee-30b90a87f507","tags":[]},{"id":"poem-465e274a89e922920fd588ad","title":"九月二日","author":"陈造","dynasty":"宋","verses":["灯火一樽酒，笑语亦固然。","如何棘围夜，忆归不成眠。","衰怀动多感，妻儿须眼前。","人生四方志，谁遣霜覆颠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4869ad66-b6c9-451b-90c4-35ca76e1b8d2","tags":[]},{"id":"poem-4661bc6a96ccc662b2123e9f","title":"五言戏赠吕神童行","author":"严焕","dynasty":"宋","verses":["自我诹人物，天涯实眇然。","晚观童子意，早拍病夫肩。","凛凛神锋异，琅琅腹笥传。","晴温武林道，光怪吕家船。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-429afb36-2c18-4f88-b106-ce7d81dc754f","tags":[]},{"id":"poem-4661bf4c9747f45c98183c53","title":"感遇十二首 七","author":"张九龄","dynasty":"唐","verses":["江南有丹橘，经冬犹绿林。","岂伊地气暖，自有岁寒心。","可以荐嘉客，奈何阻重深。","运命唯所遇，循环不可寻。","徒言树桃李，此木岂无阴。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-11b013f9-aa6a-4e55-8e68-195dc62f161f","tags":["唐诗三百首","寓人","五言古诗","咏物","人格","咏物诗","写树"]},{"id":"poem-466aa12f9d22bd4bdf3516b5","title":"燕堂诗","author":"蔡兹","dynasty":"宋","verses":["世情日浅道情深，悔不林泉早脱簪。","一世简编贻后叶，百年香火奉先心。","诗缘好句须亲录，酒到浓时辄倩斟。","于此更无关意事，时携诸幼步花阴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-20b9797c-f60f-47d8-b2bb-e845ca7f08aa","tags":[]},{"id":"poem-467280389ca3d72b0fd33411","title":"南池","author":"赵嘏","dynasty":"唐","verses":["照影池边多少愁，往来重见此塘秋。","芙蓉苑外新经雨，红叶相随何处流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a7f13f76-a9a2-4d24-9260-0a30faab44ff","tags":[]},{"id":"poem-4673ed7bc6ea69fa218ecbbc","title":"府试观开元皇帝东封图","author":"马戴","dynasty":"唐","verses":["俨若翠华举，登封图乍开。","冕旒明主立，冠剑侍臣陪。","迹类飞仙去，光同拜日来。","粉痕疑检玉，黛色讶生苔。","挂壁云将起，陵风仗若回。","何年复东幸，鲁叟望悠哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-31d6dc34-ddcf-479d-975d-7159a00da2b9","tags":[]},{"id":"poem-467884bc1baf330efb1bad68","title":"宇文秀才斋中海柳咏","author":"孟郊","dynasty":"唐","verses":["玉缕青葳蕤，结为芳树姿。","忽惊明月钩，钩出珊瑚枝。","灼灼不死花，蒙蒙长生丝。","饮栢泛仙味，咏兰拟古词。","霜风清飕飕，与君长相思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-942d1b0c-771a-46c9-b66a-bf00da520b83","tags":[]},{"id":"poem-4683cea3a12441229521e6ce","title":"南亭","author":"赵嘏","dynasty":"唐","verses":["孤亭影在乱花中，怅望无人此醉同。","听尽暮钟犹独坐，水边襟袖起春风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a65f7dff-61ac-4c5e-aa5e-30bf1946c60d","tags":[]},{"id":"poem-468a82be6bc7ded3b68979e1","title":"题处士林亭","author":"李涛","dynasty":"唐","verses":["帝里高人宅，苍苔遶径深。","卷帘山入户，摘菓鸟移林。","石沼养龟水，月台留客琴。","生涯一樽酒，名利不关心。","（同前第五册第三一二三页。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7c8c560f-c7d3-4d76-9fb6-d6d787ad7344","tags":[]},{"id":"poem-468b56a39ae4d3ddd4d772e4","title":"插花三台令","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(众舞)打和鼓乔妆三教，舞狮豹间着大旗。","小二哥敲罗击鼓，使牛儿萧笛乱吹，浪猪娘先呈百戏，驷马勒妆神跳鬼。","牛筋引鼠哥一队，忙行走竹马似飞。","(舞下。","外、老旦、旦)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8804","tags":[]},{"id":"poem-468fa629fcbd906a131311dc","title":"宿西禅寺诗","author":"华镇","dynasty":"宋","verses":["湖湘跋涉今犹近，淮海漂流昔早曾。","扰扰未能逃鞅掌，星星祇见变鬅鬙。","驱车旷野犹飞雪，税驾闲窗已上灯。","瓶锡不移缘累息，须知人世尽输僧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-17d1bb00-7ed3-4031-92b0-36657ceabd65","tags":[]},{"id":"poem-46937ef0305c2a4505b68c95","title":"鹧鸪天·却月凌风度雪清","author":"孔矩","dynasty":"宋","verses":["却月凌风度雪清。","何郎高咏照花明。","一枝弄碧传幽信，半额涂黄拾晚荣。","春思淡，暗香轻。","江南雨冷若为情。","犹胜远隔潇湘水，忽到窗前梦不成。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-581","tags":[]},{"id":"poem-469db1a0dec020b9e16ed813","title":"郊庙歌辞 享隐太子庙乐章 肃和","author":"不详","dynasty":"唐","verses":["岁肇春宗，干开震长。","瑶山既寂，戾园斯享。","玉肃其事，物昭其象。","弦诵成风，笙歌合响。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fce85010-8fcb-42b5-8ac1-db094c76e69e","tags":[]},{"id":"poem-46a47fa61296a1c3310f41fc","title":"偈颂（幷序○序为南岳齐己撰） 九十","author":"居遁","dynasty":"唐","verses":["龙牙山里龙，形非世间色。","世上画龙人，巧巧描不得。","唯有识龙人，一见便心息。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-93fc8780-1256-4046-97ca-49bf7938ca31","tags":["衡山"]},{"id":"poem-46a8a9f6521ddb53df83b9a0","title":"诗品二十四则 雄浑","author":"司空图","dynasty":"唐","verses":["大用外腓，真体内充。","返虚入浑，积健为雄。","具备万物，横绝太空。","荒荒油云，寥寥长风。","超以象外，得其环中。","持之匪强，来之无穷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b5a93088-0dcb-49d7-baa0-38d17360acb4","tags":[]},{"id":"poem-46abbf82462e6b3171e7b5ad","title":"昉著灸数朝废吟累日继披佳什莫匪正声亦贡七章补为十首学颦之诮诚所甘心  其一","author":"李昉","dynasty":"宋","verses":["心情休问近何如，冉冉浮生六十余。","抱病久无欢笑兴，信缘慵答往还书。","容颜也道随年改，牙齿谁教斗顿疏。","何处此身堪养老，万安山下有村居。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-01145823-eaeb-41b6-a22c-514f97b5ca3c","tags":[]},{"id":"poem-46b1b8a15c89ea4351048ff3","title":"东门送客","author":"李端","dynasty":"唐","verses":["绿杨新草路，白发故乡人。","既壮还应老，游梁复滞秦。","逢花莫漫折，能有几多春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3cd9a856-d137-4760-8431-47fd482be3d3","tags":[]},{"id":"poem-46b1c676755bbe9da8ec6e9f","title":"渔父词・渔父·花姑溪上鹭鸶滩","author":"周紫芝","dynasty":"宋","verses":["花姑溪上鹭鸶滩。","辜负渔竿二十年。","无可载，不抛官。","携取全家去不难。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-511","tags":[]},{"id":"poem-46b1e0cf7419a60ebce135dc","title":"望湘人·厌莺声到枕","author":"贺铸","dynasty":"宋","verses":["厌莺声到枕，花气动帘，醉魂愁梦相半。","被惜馀薰，带惊剩眼。","几许伤春春晚。","泪竹痕鲜，佩兰香老，湘天浓暖。","记小江、风月佳时，屡约非烟游伴。","须信鸾弦易断。","奈云和再鼓，曲终人远。","认罗袜无踪，旧处弄波清浅。","青翰棹舣，白苹洲畔。","尽木临皋飞观。","不解寄、一字相思，幸有归来双燕。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-105","tags":["宋词三百首"]},{"id":"poem-46b2fad9758393f0c483d77a","title":"秋夜月","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(外)吾表文，奏上朝廷去，我王必降天恩露，加官进禄封贤妇。","因祸致福，因祸致福。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1950","tags":[]},{"id":"poem-46b5140c2a0539335f9952d7","title":"德升尚书再用前韵见示五绝 对客隐几","author":"綦崇礼","dynasty":"宋","verses":["边书犹插羽，世用在持矛。","空言客何务，问事其少休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2d794639-3876-490c-94e4-21a3c6dc1cf9","tags":[]},{"id":"poem-46b94788443f5dfb33877203","title":"文宗嗜蛤蜊","author":"释了惠","dynasty":"宋","verses":["螺师蚌蛤类，大唐天子心。","嗜好即深信，南无观世音。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4fa68ea9-9672-4b5b-bbb7-70d7d048a16f","tags":[]},{"id":"poem-46c508aadcc63b2607d88fb6","title":"忆远","author":"张籍","dynasty":"唐","verses":["行人犹未有归期，万里初程日暮时。","唯爱门前双柳树，枝枝叶叶不相离。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4488fc89-5956-4d50-8312-544f7126e8b4","tags":[]},{"id":"poem-46d5aa0c49e7f83e7c9f3888","title":"清平乐·断桥缺月","author":"李弥逊","dynasty":"宋","verses":["断桥缺月。","点点枝头雪。","画角吹残声未歇。","早是一年春别。","寿阳弄粉成妆。","柔肠结结丁香。","可怕真梅轻妒，游蜂说与何妨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-38","tags":[]},{"id":"poem-46da05921c954f0934d0866f","title":"隋堤怀古","author":"张祜","dynasty":"唐","verses":["隋季穷兵复濬川，自为猛虎可周旋。","锦帆东去不归日，汴水西来无尽年。","本欲山河传百二，谁知钟鼎已三千。","那堪重问江都事，回望空悲绿树烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9060e332-b72c-421c-879d-90a710e40076","tags":["忧国忧民","怀古"]},{"id":"poem-46da060c5c5456763489dff2","title":"送友人卢处士游吴越","author":"张籍","dynasty":"唐","verses":["羡君东去见残梅，惟有王孙独未回。","吴苑夕阳明古堞，越宫春草上高台。","波生野水雁初下，风满驿楼潮欲来。","试问渔舟看雪浪，几多江燕荇花开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-30a2dd04-afb6-4cf4-97f2-8ddd300ebaef","tags":[]},{"id":"poem-46dc2ecfc159c9af7e53b2ea","title":"猨","author":"张乔","dynasty":"唐","verses":["挂月栖云向楚林，取来全是为清音。","谁知系在黄金索，翻畏侯家不敢吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3df47d70-81a0-42ab-8a8b-87f11fba968f","tags":[]},{"id":"poem-46e10ea1b393d34bdb070dcc","title":"书雨","author":"孙嵩","dynasty":"宋","verses":["阴谷幽林热似焚，阿香鸣鼓骤殷殷。","天公作雨须臾事，用得东山一片云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f8f7feda-3cbf-4bfc-9b16-33b9635a8546","tags":[]},{"id":"poem-46f33c771250ba0303c35e54","title":"临江仙·柳带摇风汉水滨","author":"牛希济","dynasty":"五代","verses":["柳带摇风汉水滨，平芜两岸争匀。","鸳鸯对浴浪痕新。弄珠游女，微笑自含春。","轻步暗移蝉鬓动，罗裙风惹轻尘。","水晶宫殿岂无因？空劳牵手，解佩赠情人。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-38","tags":[]},{"id":"poem-4703d7fa20c026f795421d48","title":"访山友","author":"曹松","dynasty":"唐","verses":["一迳通高屋，重云翳两原。","山寒初宿顶，泉落未知根。","急雨洗荒壁，惊风开静门。","听君吟废夜，苦却建溪猿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b8919038-49ac-45eb-8fba-e2313a2b375d","tags":[]},{"id":"poem-470d05bfdffb899ec1d05132","title":"甘林","author":"杜甫","dynasty":"唐","verses":["舍舟越西冈，入林解我衣。","青刍适马性，好鸟知人归。","晨光映远岫，夕露见日晞。","迟暮少寝食，清旷喜荆扉。","经过倦俗态，在野无所违。","试问甘藜藿，未肯羡轻肥。","喧静不同科，出处各天机。","勿矜朱门是，陋此白屋非。","明朝步邻里，长老可以依。","时危赋敛数，脱粟为尔挥。","相携行荳田，秋花霭菲菲。","子实不得吃，货市送王畿。","尽添军旅用，迫此公家威。","主人长跪问，戎马何时稀。","我衰易悲伤，屈指数贼围。","劝其死王命，慎莫远奋飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6a3c8790-6ad2-47ce-8295-ee5512ba2d28","tags":[]},{"id":"poem-4714c1ad13ac6a173cc187bc","title":"朝中措·灯花挑尽夜将阑","author":"张抡","dynasty":"宋","verses":["灯花挑尽夜将阑。","斜掩小屏山。","一点凉蟾窥慢，钏敲玉臂生寒。","起来无绪，炉薰烬冷，桐叶声干。","都把沈思幽恨，明朝分付眉端。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-889","tags":[]},{"id":"poem-47193bf167fc684f14a4c2f8","title":"西江月·风送丹枫卷地","author":"葛立方","dynasty":"宋","verses":["风送丹枫卷地，霜干枯苇鸣溪。","兽炉重展向深闺。","红入麒麟方炽。","翠箔底垂银蒜，罗帏小钉金泥。","笙歌送我玉东西。","谁管摇花舞砌。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-522","tags":[]},{"id":"poem-4727ddd34a8c87a2991688ab","title":"杭州天竺灵隐二寺顷岁亦布衣一游及赴镇会稽不敢以登临自适竟不复到寺寺多猨猱谓之孙团弥长其类因追思为诗二首 一","author":"李绅","dynasty":"唐","verses":["翠岩幽谷高低寺，十里松风碧嶂连。","开尽春花芳草涧，徧通秋水月明泉。","石文照日分霞壁，竹影侵云拂暮烟。","时有猨猱扰钟磬，老僧无复得安禅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-58542b87-49af-459c-b37d-aec1d72a7855","tags":[]},{"id":"poem-4728b3b1d7055dd8b2f08edc","title":"云庵","author":"释原妙","dynasty":"宋","verses":["或淡或浓拖雨去，半舒半卷逆风来。","为怜途路无栖泊，却把柴扉永夜开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6cf7a70d-79e2-47bd-af44-330d95b69a1e","tags":[]},{"id":"poem-472deb3a9c0aefcd118cc521","title":"寄僧野和尚","author":"贯休","dynasty":"唐","verses":["鸟外更谁亲，诸峰即四邻。","白头寒枕石，青衲烂无尘。","橡栗堆行径，猨猴遶定身。","傥然重结社，愿作扫坛人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-fd191111-d21a-4629-b8ea-746b065847e0","tags":[]},{"id":"poem-472fd352b2655e05658ef3bc","title":"题嘉祥驿","author":"孟迟","dynasty":"唐","verses":["树顶烟微绿，山根菊暗香。","何人独鞭马，落日上嘉祥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-62f6476e-dcd2-45e5-be2a-71f958e24e4d","tags":[]},{"id":"poem-4734952c7f70add2a157ead0","title":"酬姚补阙南仲云溪馆中戏题随书见寄","author":"皎然","dynasty":"唐","verses":["寺溪临使府，风景借仁祠。","补衮周官贵，能名汉主思。","卧云知独处，望月忆同时。","忽枉缄中赠，琼瑶满手持。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-26add434-21ca-44c0-bc88-35d8861735e9","tags":[]},{"id":"poem-473fc3603ed2778d59516de2","title":"法曲献仙音·庭叶飘寒","author":"方千里","dynasty":"宋","verses":["庭叶飘寒，砌蛩催织，夜色迢迢难度。","细剔灯花，再添香兽，凄凉洞房朱户。","见凤枕羞孤另，相思洒红雨。","有谁语。","道年来，为郎憔悴，音问隔，回首后期尚阻。","寂寞两愁山，锁闲情、无限颦妩。","嫩雪消肌，试罗衣、宽尽腰素。","问何时梦里，趁得好风飞去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-514","tags":[]},{"id":"poem-4744d24a28cf7afa88bd9330","title":"春泛若耶溪","author":"綦毋潜","dynasty":"唐","verses":["幽意无断绝，此去随所偶。","晚风吹行舟，花路入溪口。","际夜转西壑，隔山望南斗。","潭烟飞溶溶，林月低向后。","生事且弥漫，愿为持竿叟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6290b8f0-48de-407f-be2c-629140d91f83","tags":["唐诗三百首","抒情","五言古诗"]},{"id":"poem-4760582f4cfbfbed41460efc","title":"江行无题一百首 四十三","author":"钱珝","dynasty":"唐","verses":["兵火有余烬，贫村才数家。","无人争晓渡，残月下寒沙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-48d1ff68-1738-45d9-8041-c9f475b7bb02","tags":[]},{"id":"poem-4770a1ab0afaef461ff7d32c","title":"赏宫花","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(末)你两个歹凶，拐钱图使用。","怎知遇着我，你手拿空。","(合)好似雁从天上过，急忙归去炒油葱。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1784","tags":[]},{"id":"poem-47774a8a777d31727d701d5e","title":"偈颂（幷序○序为南岳齐己撰） 七十二","author":"居遁","dynasty":"唐","verses":["唯念门前树，能容鸟泊栖（《景德传灯录》卷二九作「飞」）。","来者无心唤，腾身不慕归。","若人心似树，与道不相违。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7f0a38a7-f9c0-49d8-8e0a-d5c1e2ec3f18","tags":["衡山"]},{"id":"poem-4778f2e212cf625f2e8d0f1e","title":"端康之间地名越城五山秀峙有蜿蜒飞跃之状山有五龙庙当秦时神媪临江五龙从之游没葬山上庙祀至今灵响甚著乡人以风雨候龙之归因作送迎辞五绝句以遗之  其一","author":"李纲","dynasty":"宋","verses":["风雨潇潇云气浮，五龙归觐到灵湫。","星霜换易江山在，尚忆当年水际游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a0e8ec3b-648a-4443-a91b-bf1089edff0e","tags":[]},{"id":"poem-477af587b656717053cad0d9","title":"浣溪沙·风送清香过短墙","author":"黄公度","dynasty":"宋","verses":["风送清香过短墙。","烟笼晚色近修篁。","夕阳楼外角声长。","欲去还留无限思，轻匀淡抹不成妆。","一尊相对月生凉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-444","tags":[]},{"id":"poem-477d681258fbff70fefc3a99","title":"喜雨呈安国  其二","author":"张栻","dynasty":"宋","verses":["早秧出陇蚕已丝，眼中一雨正垂垂。","农家辛苦渠能识，请诵周公七月诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-68f19544-338c-48fc-bcc2-b2395366a2e1","tags":[]},{"id":"poem-4789583778990585a05192fd","title":"如鱼水·帝里疏散","author":"柳永","dynasty":"宋","verses":["帝里疏散，数载酒萦花系，九陌狂游。","良景对珍筵恼，佳人自有风流。","劝琼瓯。","绛唇启、歌发清幽。","被举措、艺足才高，在处别得艳姬留。","浮名利，拟拼休。","是非莫挂心头。","富贵岂尤人，时会高志须酬。","莫闲愁。","共绿蚁、红粉相尤。","向绣幄，醉倚芳姿睡，算除此外何求。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-186","tags":[]},{"id":"poem-479377a2ee30b127d3c8fb32","title":"南歌子·古戍","author":"纳兰性德","dynasty":"清","verses":["古戍饥乌集，荒城野雉飞。","何年劫火剩残灰，试看英雄碧血，满龙堆。","玉帐空分垒，金笳已罢吹。","东风回首尽成非，不道兴亡命也，岂人为。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-156","tags":[]},{"id":"poem-479bf17616e07051533ce582","title":"颂古七十六首  其二五","author":"释士珪","dynasty":"宋","verses":["若谓平常心是道，枝蔓向上更生枝。","贴肉汗衫如脱了，唤来眼上与安眉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-25b6d4ba-0a87-4744-9a88-42e7a3cea7e1","tags":[]},{"id":"poem-47a9e8260d295ea5ff09dfb5","title":"鹿门寺","author":"裴说","dynasty":"唐","verses":["鹿门山上寺，突兀尽无尘。","到此修行者，应非取次人。","鸟过惊石磬，日出碍金身。","何计生烦恼，虚空是四邻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c04e408e-84bb-4e11-8a4c-59881a0cabfa","tags":[]},{"id":"poem-47b105d808f1068dbdebd435","title":"凫鹥","author":"佚名","dynasty":"先秦","verses":["凫鹥在泾，公尸在燕来宁。尔酒既清，尔肴既馨。公尸燕饮，福禄来成。","凫鹥在沙，公尸来燕来宜。尔酒既多，尔肴既嘉。公尸燕饮，福禄来为。","凫鹥在渚，公尸来燕来处。尔酒既湑，尔肴伊脯。公尸燕饮，福禄来下。","凫鹥在潀，公尸来燕来宗，既燕于宗，福禄攸降。公尸燕饮，福禄来崇。","凫鹥在亹，公尸来止熏熏。旨酒欣欣，燔炙芬芬。公尸燕饮，无有后艰。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-247","tags":[]},{"id":"poem-47b4b7c62f9c358811c9fb24","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(净、丑)你杀了人，使孙荣埋尸葬躯。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1937","tags":[]},{"id":"poem-47bf07648b789b3f04293ec3","title":"孺子祠堂","author":"释居简","dynasty":"宋","verses":["钩党开端惨弗舒，悬知隠逸未全疎。","奸谀孔炽吾何与，名节虽高弊不除。","盟鹭相忘寻水宿，冥鸿那复死巢居。","澜翻平地浑漂汩，柰此悠然一叶虚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9da5f6e0-81a1-483d-945c-c2789c8af73a","tags":[]},{"id":"poem-47d7c5df6a2e2444f0401c15","title":"送刘山阳","author":"徐铉","dynasty":"宋","verses":["旧族知名士，朱衣宰楚城。","所嗟吾道薄，岂是主恩轻。","战鼓何时息，儒冠独自行。","此心多感激，相送若为情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c48f4ea5-666e-4f98-9511-5d841821c9ca","tags":[]},{"id":"poem-47e56eb37bdb1ac7f9b2d523","title":"挽颐轩张朝奉  其二","author":"王柏","dynasty":"宋","verses":["挺挺长松施女萝，平生能得几相过。","𰬸帷远辱双絇临，泪眼犹瞻两鬓皤。","曾未经年成契阔，至今一恸竟蹉跎。","吉人已矣难重见，山口凄凄薤露歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-74a629ff-ba28-4f67-a8bb-d35c4d3e7a84","tags":[]},{"id":"poem-47ec8d605a930e904800782c","title":"仙客","author":"李昉","dynasty":"唐","verses":["胎化仙禽性本殊，何人携尔到京都。","因加美号为仙客，称向闲庭伴野夫。","警露秋声云多远，翘沙晴影月中孤。","青田万里终归去，暂处鸡群莫叹吁。","（见《宋诗纪事》卷二。","）（见《瀛奎律髓》卷二七。","）（〖1〗《青箱杂记》〖宋吴处厚撰〗：「昉所畜五禽，名五客，仙客鹤，雪客鹭，闲客白鹇，陇客南客孔雀，西客鹦鹉，有诗云。","」〖今本《青箱杂记》无此条。","〗）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1aa86ed4-14da-4c5a-a9c6-a0872cabdb12","tags":[]},{"id":"poem-47f0fc9f5bf122c81f1ec063","title":"某忝被给札之召伏蒙景纯学士文丈宠示嘉篇且述早岁先人试职之日尝亦相遇于政府感怆不已辄次高韵","author":"苏颂","dynasty":"宋","verses":["先友勤渠庆得时，相逢仍在右垣扉。","负山徒荷君恩重，起草多惭笔力微。","早岁应门叨赏识，几年联襼接音徽。","雕章华藻蒙褒贲，知我从今不患稀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-52fe6939-0c8f-47cb-a425-ff744893ae67","tags":[]},{"id":"poem-47f26382f596bc06a7bce7f5","title":"北归将自英韶趋江表因游清远峡碧落洞谒六祖于曹溪望韶石渡庾岭皆峤南绝景也适江西道梗遵海而归此志不遂赋五绝见意 韶石","author":"李纲","dynasty":"宋","verses":["重华南狩到炎荒，髙会群神广乐张。","岂独有情能率舞，至今峰石亦低昂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-76d1b1ab-059b-42cb-a4b6-d88331a86a70","tags":[]},{"id":"poem-47f86932e7063bbdb81ce359","title":"咏𡱈","author":"张𬸦","dynasty":"唐","verses":["勒腰须巧快，捺脚更风流。","但令细眼合，人自分轮筹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-617b8954-16d6-40fb-9373-2608f127af6a","tags":[]},{"id":"poem-481476b333ff6961c0c3ed10","title":"九歌·湘夫人","author":"屈原","dynasty":"先秦","verses":["帝子降兮北渚，目眇眇兮愁予。","袅袅兮秋风，洞庭波兮木叶下。","登白薠兮骋望，与佳期兮夕张。","鸟何萃兮苹中，罾何为兮木上？","沅有茝兮醴有兰，思公子兮未敢言。","荒忽兮远望，观流水兮潺湲。","麋何食兮庭中，蛟何为兮水裔。","朝驰余马兮江皋，夕济兮西澨。","闻佳人兮召余，将腾驾兮偕逝。","筑室兮水中，葺之兮荷盖。","荪壁兮紫坛，播芳椒兮成堂。","桂栋兮兰橑，辛夷楣兮药房。","罔薜荔兮为帷，擗蕙櫋兮既张。","白玉兮为镇，疏石兰兮为芳。","芷葺兮荷屋，缭之兮杜衡。","合百草兮实庭，建芳馨兮庑门。","九嶷缤兮并迎，灵之来兮如云。","捐余袂兮江中，遗余褋兮醴浦。","搴汀洲兮杜若，将以遗兮远者。","时不可兮骤得，聊逍遥兮容与！"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-4","tags":[]},{"id":"poem-481d28f9ac3594b2bd37e5af","title":"鹧鸪天·池上红衣伴倚阑","author":"吴文英","dynasty":"宋","verses":["池上红衣伴倚阑。","栖鸦常带夕阳还。","殷云度雨疏桐落，明月生凉宝扇闲。","乡梦窄，水天宽。","小窗愁黛澹秋山。","吴鸿好为传归信，杨柳阊门屋数间。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-85","tags":["宋词三百首"]},{"id":"poem-4822f34ba710aa464529a230","title":"柳枝·狂雪随风扑马飞","author":"牛峤","dynasty":"五代","verses":["狂雪随风扑马飞，惹烟无力被春欺。","莫教移入灵和殿，宫女三千又妒伊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-48","tags":[]},{"id":"poem-48263184abec7b9640d1ebe3","title":"再用韵奉谢德升尚书见和且以解嘲","author":"綦崇礼","dynasty":"宋","verses":["西风醒梦入秋堂，梦境还空寄短章。","妄见徒嗟妨睡美，闲心久谢趁朝忙。","流年倐忽身今老，荣路斯须味已忘。","惭愧君诗真戏谑，邯郸自警亦何伤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-4168ab71-1b7f-4b64-937c-0ca1b62c9471","tags":[]},{"id":"poem-4826320135224b9cca982102","title":"郊庙歌辞 封泰山乐章 雍和","author":"张说","dynasty":"唐","verses":["俎豆有馥，粢盛洁丰。","亦有和羹，既戒既平。","钟鼓管磬，肃唱和鸣。","皇皇后祖，来我思成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6bd61d48-95a3-4505-a201-27a22d06f17a","tags":["泰山"]},{"id":"poem-48268dc60ad65e2c0d6335c5","title":"柳梢青·惊世文章","author":"崔敦礼","dynasty":"宋","verses":["惊世文章，门户照人，外家衣钵。","多谢温存，相期宅相，此恩难说。","今朝祝寿樽前，共拜舞、诸孙下列。","但愿从今，一年强似，一年时节。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-403","tags":[]},{"id":"poem-483dd30c6460437a846f626d","title":"寄春坊顾校书","author":"刘得仁","dynasty":"唐","verses":["宁因不得志，寂寞本相宜。","冥目冥心坐，花开花落时。","数畦蔬甲出，半梦鸟声移。","只恐龙楼吏，归山又见违。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4c73eb1e-1e2f-40de-90cd-2857e6935596","tags":[]},{"id":"poem-483e265e3cd5476e874d33d3","title":"邻相反行","author":"薛逢","dynasty":"唐","verses":["东家有儿年十五，只向田园独辛苦。","夜开沟水遶稻田，晓叱耕牛垦塉土。","西家有儿才弱龄，仪容清峭云鹤形。","涉书猎史无早暮，坐期朱紫如拾青。","东家西家两相诮，西儿笑东东又笑。","西云养志与荣名，彼此相非不同调。","东家自云虽辛苦，躬耕早暮及所亲。","男舂女爨二十载，堂上未为衰老人。","朝机暮织还充体，余者到兄还及弟。","春秋伏腊长在家，不许妻奴暂违礼。","尔今二十方读书，十年取第三十余。","往来途路长离别，几人便得升公车。","纵令得官身须老，衔恤终天向谁道。","百年骨肉归下泉，万里枌榆长秋草。","我今躬耕奉所天，耘锄刈获当少年。","面上笑添今日喜，肩头薪续厨中烟。","纵使此身头雪白，又有儿孙还稼穑。","家藏一卷古孝经，世世相传皆得力。","为报西家知不知，何须谩笑东家儿。","生前不得供甘滑，殁后扬名徒尔为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-74f58e76-5109-410a-b85f-6c03da624eba","tags":[]},{"id":"poem-483e382dc38daf4366c6f67f","title":"山居四感 噪蝉","author":"李纲","dynasty":"宋","verses":["修竹茂林山寺幽，蝉声如沸满清秋。","吸风饮露无求世，嘒嘒何为噪不休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-969ab3d0-4336-4c2d-9b3f-e8f464bb12e6","tags":[]},{"id":"poem-483e6395a075500fd90ffbc7","title":"韦讽录事宅观曹将军画马图","author":"杜甫","dynasty":"唐","verses":["国初已来画鞍马，神妙独数江都王。","将军得名三十载，人间又见真乘黄。","曾貌先帝照夜白，龙池十日飞霹雳。","内府殷红马脑盌，倢伃传诏才人索。","盌赐将军拜舞归，轻纨细绮相追飞。","贵戚权门得笔迹，始觉屏障生光辉。","昔日太宗拳毛䯄，近时郭家师子花。","今之新图有二马，复令识者久叹嗟。","此皆骑战一敌万，缟素漠漠开风沙。","其余七匹亦殊绝，迥若寒空动烟雪。","霜蹄蹴踏长楸间，马官厮养森成列。","可怜九马争神骏，顾视清高气深稳。","借问苦心爱者谁，后有韦讽前支遁。","忆昔巡幸新丰宫，翠华拂天来向东。","腾骧磊落三万匹，皆与此图筋骨同。","自从献宝朝河宗，无复射蛟江水中。","君不见金粟堆前松柏里，龙媒去尽鸟呼风。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-827e44b1-7064-4ff7-9a9c-192eece94e2d","tags":["唐诗三百首","写马","七言古诗","题画","马"]},{"id":"poem-484f59d10a4bed42f08f4f03","title":"姚宰行可和诗索墨酬以元韵  其二","author":"王十朋","dynasty":"宋","verses":["人生几丸墨，老病厌操持。","好与贤明宰，研磨共救时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f367b333-12b8-475f-8581-90b4cc9c15e1","tags":[]},{"id":"poem-484fef0827b53e69b5d32f9f","title":"送杨敬之倅湖南","author":"李涉","dynasty":"唐","verses":["久嗟尘匣掩青萍，见说除书试一听。","闻君却作长沙傅，便逐秋风过洞庭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-95f586e7-f277-4eb0-ac7f-b9304458f354","tags":["洞庭湖"]},{"id":"poem-4857c70cf241907730b2b73e","title":"梦江南·新来好","author":"纳兰性德","dynasty":"清","verses":["新来好，唱得虎头词。","一片冷香唯有梦，十分清瘦更无诗。","标格早梅知。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-117","tags":[]},{"id":"poem-485954d72ceb198df7f1ec5d","title":"玉女杜兰香下嫁于张硕","author":"曹唐","dynasty":"唐","verses":["天上人间两渺茫，不知谁识杜兰香。","来经玉树三山远，去隔银河一水长。","怨入清尘愁锦瑟，酒倾玄露醉瑶觞。","遗情更说何珍重，擘破云鬟金凤皇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3f65f20f-056b-4a05-bc38-7b05ce3f428a","tags":[]},{"id":"poem-485ee21852d4a4740bf81cd7","title":"新秋雨霁宿王处士东郊","author":"马戴","dynasty":"唐","verses":["夕阳逢一雨，夜木洗清阴。","露气竹窗静，秋光云月深。","煎尝灵药味，话及故山心。","得意两不寐，微风生玉琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0af77225-ddfd-43f8-9ec8-9851edfdd917","tags":[]},{"id":"poem-486db76158101548a2d84491","title":"日者","author":"释居简","dynasty":"宋","verses":["恶月悬弧岂好儿，衣冠聊复换伽黎。","听言易感人人信，不信田文善相齐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-b66f6bc6-70bc-439e-9ff5-c2aa5f34fc4c","tags":[]},{"id":"poem-4874dd155d98abd1ef6348ab","title":"观别者","author":"王维","dynasty":"唐","verses":["青青杨柳陌，陌上别离人。","爱子游燕赵，高堂有老亲。","不行无可养，行去百忧新。","切切委兄弟，依依向四邻。","都门帐饮毕，从此谢亲宾。","挥涕逐前侣，含凄动征轮。","车徒望不见，时见起行尘。","吾亦辞家久，看之泪满巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-82838e54-b4dc-4663-91e8-60e0d4f0e9a2","tags":["离别","无奈","漂泊"]},{"id":"poem-4877f21056ff44dd97a7c26e","title":"题三学院经楼","author":"段义宗","dynasty":"唐","verses":["鹫岭鸡园不可俦，叨陪龙象喜登游。","玉排复道珊瑚殿，金错危栏翡翠楼。","尚欲归心求四谛，敢辞旋绕满三周。","羲和鞭挞金乌疾，欲网无由肯驻留？","（同前《鉴诫录》卷六。","《全唐诗》佚句卷只存三、四句。","此诗第四句「危栏」，《全唐诗》作「危椆」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3e26e619-0333-434f-b830-ce9a366ca837","tags":[]},{"id":"poem-48796927c8fe66b099df126b","title":"春夜宿云际寺","author":"斐公衍","dynasty":"唐","verses":["境静闻钟声易响，庭高见月影难沈。","青山解隔尘中事，流水能清物外心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-740c1743-61f4-4694-908b-6737af54523d","tags":[]},{"id":"poem-488d855e01cbbdb2ac3df3e3","title":"江行无题一百首 二十二","author":"钱珝","dynasty":"唐","verses":["带舟维古岸，还似阻西陵。","箕伯无多怒，回头讵不能。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4bd471e6-b92f-42a0-82ce-d56228ad0cf3","tags":[]},{"id":"poem-488defd5309c83a2c3237a6e","title":"渔歌子·柳垂丝","author":"李珣","dynasty":"五代","verses":["柳垂丝，花满树，莺啼楚岸春山暮。","棹轻舟，出深浦，缓唱渔歌归去。","罢垂纶，还酌醑，孤村遥指云遮处。","下长汀，临浅渡，惊起一行沙鹭。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-19","tags":[]},{"id":"poem-488fe749d4cad978f1e487a0","title":"咏手二首 二","author":"赵光远","dynasty":"唐","verses":["撚玉搓琼软复圆，绿窗谁见上琴弦。","慢笼彩笔闲书字，斜指瑶阶笑打钱。","炉面试香添麝炷，舌头轻点贴金钿。","象床珍簟宫棋处，拈定文楸占角边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a774e867-f248-4c5f-a140-df0b32839c61","tags":[]},{"id":"poem-489086da1737352a88455562","title":"蕉园","author":"纳兰性德","dynasty":"清","verses":["见说斋坦闭，前朝大乙祠。","莺边花树树，燕外柳丝丝。","宫御人稀少，词臣例许窥。","今朝陪豹尾，新长万年枝。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-240","tags":[]},{"id":"poem-48a6ddfb81bb25b46c05cb17","title":"春日又送潘述之扬州","author":"皎然","dynasty":"唐","verses":["别渚望邗城，岐路春日徧。","柔风吹杨柳，芳景流郊甸。","日日东林期，今夕异乡县。","文房旷佳士，禅室阻清盼。","离恨夺赏心，不得谐所愿。","莫忆山中人，碧云遥可见。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-50bd8261-d9b9-4f9b-9c4e-7520bfb16325","tags":[]},{"id":"poem-48a8a7c2cd31a881c9f31d22","title":"仙子洞中有怀刘阮","author":"曹唐","dynasty":"唐","verses":["不将清瑟理霓裳，尘梦那知鹤梦长。","洞里有天春寂寂，人间无路月茫茫。","玉沙瑶草连溪碧，流水桃花满涧香。","晓露风灯零落尽，此生无处访刘郎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a5b6e597-69ab-48d4-b1e1-ad180c6dcb2a","tags":[]},{"id":"poem-48b354f9986551f50413070a","title":"十二咏 双莲阁","author":"李纲","dynasty":"宋","verses":["并蔕芙蓉出绿波，靓粧鸾鉴照双娥。","风清月晓微开处，无那幽人独见何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d56e5828-f929-48a8-9eaf-0ba3954c9cda","tags":[]},{"id":"poem-48b91b7e6ca690906ec205f8","title":"饯中书侍郎来济","author":"太宗皇帝","dynasty":"唐","verses":["暧暧去尘昏灞岸，飞飞轻盖指河梁。","云峰衣结千重叶，雪岫花开几树妆。","深悲黄鹤孤舟远，独叹青山别路长。","聊将分袂沾巾泪，还用持添离席觞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8c6e81ed-cfe2-4900-aa3b-9d44ef7f1bea","tags":[]},{"id":"poem-48bbad39416d86b64eb9b32d","title":"赠棋僧侣","author":"张乔","dynasty":"唐","verses":["机谋时未有，多向弈棋销。","已与山僧敌，无令海客饶。","静驱云阵起，疎点鴈行遥。","夜雨如相忆，松窗更见招。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9d82ff7b-35f6-46fc-9d3c-ebfbd55d0b86","tags":[]},{"id":"poem-48c4ab4c853af3b75108b0fe","title":"水红花","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)忆昔歌舞宴楼台，会金钗。","欢娱难再。","(生)思之诗酒看书斋，命多乖，风光难再。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2954","tags":[]},{"id":"poem-48c515e694a551281a3dc548","title":"采桑子·咏春雨","author":"纳兰性德","dynasty":"清","verses":["嫩烟分染鹅儿柳，一样风丝。","似整如欹，才着春寒瘦不支。","凉侵晓梦轻蝉腻，约略红肥。","不惜葳蕤，碾取名香作地衣。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-197","tags":[]},{"id":"poem-48cf70b8d9c75a7ee104912b","title":"马诗二十三首 十八","author":"李贺","dynasty":"唐","verses":["伯乐向前看，旋毛在腹间。","祗今掊白草，何日蓦青山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cb5a4269-c06a-4c8a-bb03-a65a24b5baeb","tags":["马","写马","愤慨","怀才不遇"]},{"id":"poem-48d56a7d5c0f9c8caa143b86","title":"捣练子·心自小","author":"李石","dynasty":"宋","verses":["心自小，玉钗头。","月娥飞下白苹洲。","水中仙，月下游。","江汉佩，洞庭舟。","香名薄幸寄青楼。","问何如，打泊浮。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-280","tags":["洞庭湖"]},{"id":"poem-48e63d7e0ec3f753e4221c87","title":"次韵签判梁寺丞阻水见寄","author":"苏颂","dynasty":"宋","verses":["京府偕趋幕，弥年接坐隅。","驽骀攀骥足，鱼目混骊珠。","风谊敦贪薄，吹嘘变朽枯。","交亲齐鲁卫，政事拟阿蒲。","契合宁容间，情通不鄙无。","邀欢困萍蚁，较味賸莼鲈。","气盛吞云梦，文雄猎具区。","报投均缟纻，应和念篪竽。","巢阁行观凤，为裘伫荐狐。","世家传鹊瑞，职业在鸿都。","耸壑方腾干，乘风好纵舻。","一飞尝得志，平步即夷涂。","见比亲琼树，清如隠玉壶。","终当拾青紫，讵止学盘盂。","少别如旬日，相望似五湖。","荒郊逢辙涸，激水待云肤。","窟穴增蛇鼠，腥臊恶蚋蛄。","尊思孔北海，釜叹范莱芜。","始见生蓂魄，俄惊绕树乌。","初犹甘杞菊，久渐厌粱苽。","昼咏依依柳，宵看历历榆。","晨兴常过午，朝膳每通晡。","闲逸输吾子，驰驱属鄙夫。","无因随李郭，长日想田苏。","沙涨舟犹胶，河流轨不濡。","行邮才咫尺，命驾只须臾。","坐俟聆金玉，来应笑碔砆。","多惭昏钝枣，难慕湛精醐。","安得生双翼，徒然处橛株。","重吟赠我句，足以豁蒙愚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-cef14b02-0cad-4b24-aff5-a32e67dec8fe","tags":[]},{"id":"poem-48eb4a40f5957e2403333cd3","title":"会景堂","author":"鲜于侁","dynasty":"宋","verses":["金城环雉堞，云屋瞰阛阓。","双林耸江右，九陇觇天外。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-3707837a-0b74-4521-a13a-b60fe03da845","tags":[]},{"id":"poem-490049b865d3d79f785cde2a","title":"好事近·月色透横枝","author":"张先","dynasty":"宋","verses":["月色透横枝，短叶小花无力。","北客一声长笛，怨江南先得。","谁教强半腊前开，多情为春忆。","留取大家沈醉，正雨休风息。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-287","tags":[]},{"id":"poem-490409f38d7b2277e3c66bcb","title":"题城南书院三十四咏  其七","author":"张栻","dynasty":"宋","verses":["山色顿清秋欲半，湖光更净日平西。","凉风猎猎低荷盖，归翼翩翩度柳堤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-8e5afe4b-6462-4a63-86cf-9e46fb3a50ca","tags":[]},{"id":"poem-49046602681bdebbe7c15254","title":"折柳赠行人","author":"雍裕之","dynasty":"唐","verses":["那言柳乱垂，尽日任风吹。","欲识千条恨，和烟折一枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-84ee4182-ab14-4737-8593-1177650000e4","tags":[]},{"id":"poem-49232ded169abee0fe6acc24","title":"喜雪","author":"太宗皇帝","dynasty":"唐","verses":["碧昏朝合雾，丹卷暝韬霞。","结叶繁云色，凝璚徧雪华。","光楼皎若粉，映幕集疑沙。","泛柳飞飞絮，粧梅片片花。","照璧台圆月，飘珠箔穿露。","瑶洁短长阶，玉藂高下树。","映桐珪累白，萦峰莲抱素。","断续气将沈，徘徊岁云暮。","怀珍媿隐德，表瑞伫丰年。","橤间飞禁苑，鹤处舞伊川。","傥咏幽兰曲，同懽黄竹篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8de88b9b-bb36-4f7e-a2cd-4771ff984a8a","tags":[]},{"id":"poem-49235e14c99e9ce0627ae817","title":"木兰花令·有个人人真攀羡","author":"柳永","dynasty":"宋","verses":["有个人人真攀羡。","问著洋洋回却面。","你若无意向他人，为甚梦中频相见。","不如闻早还却愿。","免使牵人虚魂乱。","风流肠肚不坚牢，祗恐被伊牵引断。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-214","tags":[]},{"id":"poem-4926c21403f6cb2a329a27f7","title":"思归赤松村呈松阳子","author":"李德裕","dynasty":"唐","verses":["昔人思避世，惟恐不深幽。","禽庆潜名岳，鸱夷漾钓舟。","顾余知止足，所乐在归休。","不似寻山者，忘家恣远游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a7824e5f-40ca-4492-8899-8f42452a2372","tags":[]},{"id":"poem-4935a24d9d93e21ff2079cdc","title":"卜算子·新柳","author":"纳兰性德","dynasty":"清","verses":["娇软不胜垂，瘦怯那禁舞。","多事年年二月风，翦出鹅黄缕。","一种可怜生，落日和烟雨。","苏小门前长短条，即渐迷行处。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-196","tags":[]},{"id":"poem-4935c9f1f229704e68b01ae6","title":"题吴先生山居","author":"刘得仁","dynasty":"唐","verses":["先生此幽隐，便可谢人群。","潭底见秋石，树间飞霁云。","山居心已惯，俗事耳憎闻。","念我要多疾，开炉药许分。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ab5c8c16-35c2-42f5-8726-764b7ddac590","tags":[]},{"id":"poem-49369a1af97fac729b1c827a","title":"在岳咏蝉","author":"骆宾王","dynasty":"唐","verses":["西陆蝉声唱，南冠客思侵。","那堪玄鬓影，来对白头吟。","露重飞难进，风多响易沈。","无人信高洁，谁为表予心。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c65539db-4e2b-4ce4-a22b-563b6ef3f4f1","tags":["唐诗三百首","咏物","咏物诗","五言律诗"]},{"id":"poem-493d9f6b4abe2975e7140e8d","title":"送僧中孚南归","author":"谭用之","dynasty":"宋","verses":["琵琶峡口月溪边，玉乳头佗忆旧川。","一锡冷涵兰径路，片帆香挂橘洲烟。","苔封石锦栖霞室，水迸衣珠喷玉蝉。","莫道翩翩去如梦，本来吟鸟在林泉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4d564f9b-a321-4a10-8d82-a2410d7e3f18","tags":[]},{"id":"poem-4947bb3962e15ba7e463ff63","title":"句  其二","author":"谭用之","dynasty":"宋","verses":["织槛锦纹苔乍结，堕书花印菊初残。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c3407b36-206d-450e-a3c9-d20d885cc4c7","tags":[]},{"id":"poem-4953064d19293e69f7729872","title":"鹧鸪天·楼观青红倚快晴","author":"范成大","dynasty":"宋","verses":["楼观青红倚快晴。","惊看陆地涌蓬瀛。","南园花影笙歌地，东岭松风鼓角声。","山绕水，水萦城。","柳边沙外古今情。","坐中更有挥豪客，一段风流画不成。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-261","tags":[]},{"id":"poem-495ba891dac2d02a1bc4b512","title":"苏幕遮·露堤平","author":"梅尧臣","dynasty":"宋","verses":["露堤平，烟墅杳。","乱碧萋萋，雨后江天晓。","独有庾郎年最少。","窣地春袍，嫩色宜相照。","接长亭，迷远道。","堪怨王孙，不记归期早。","落尽梨花春又了。","满地残阳，翠色和烟老。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-591","tags":[]},{"id":"poem-4965168497a000125657ee7d","title":"归家山行","author":"项斯","dynasty":"唐","verses":["献赋才何拙，经时不耻归。","能知此意是，甘取众人非。","遍陇耕无圃，缘溪钓有矶。","此怀难自遣，期在振儒衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-390721dd-7011-48fd-872b-0ba53414ea40","tags":[]},{"id":"poem-496549077b874361966a274e","title":"点绛唇·阳气初生","author":"张抡","dynasty":"宋","verses":["阳气初生，万花潜动根荄暖。","暗藏芳艳。","未许东君见。","恰似温温，铅鼎丹初转。","功犹浅。","九回烹炼。","日月光华满。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-895","tags":[]},{"id":"poem-4969f991e0fa8177c9d8782c","title":"菩萨蛮 其七","author":"温庭筠","dynasty":"唐","verses":["凤凰相对盘金缕，牡丹一夜经微雨。","明镜照新妆，鬓轻双脸长。","画楼相望久，栏外垂丝柳。","音信不归来，社前双燕回。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-6","tags":[]},{"id":"poem-496a7f02125e0daf749fdc01","title":"曲江二首 二","author":"李山甫","dynasty":"唐","verses":["江色沈天万草齐，暖烟晴霭自相迷。","蜂怜杏蕋细香落，莺坠柳条浓翠低。","千队国娥轻似雪，一群公子醉如泥。","斜阳怪得长安动，陌上分飞万马蹄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-08e40e7f-b8cd-4b1a-81e5-468896d7c830","tags":[]},{"id":"poem-496af930dcd32f44f1e89596","title":"道庐陵游青原山谒保宁宗老一首","author":"李纲","dynasty":"宋","verses":["老病维摩卧七闽，欲邀瓶锡伴闲身。","愧无拂石眠云分，来作轻裘缓带人。","小队入山风袅袅，飞泉出寺石磷磷。","烦师更举西来意，一点阳和万物春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f6a2ac89-8157-4fcb-a23d-eea6f01f385a","tags":[]},{"id":"poem-496c405af48aaefedfe8222b","title":"南中客舍对雨送故人归北","author":"长孙佐辅","dynasty":"唐","verses":["猨声啾啾雁声苦，卷帘相对愁不语。","几年客吴君在楚，况送君归我犹阻。","家书作得不忍封，北风吹断堦前雨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fc27b340-1e98-48f2-b3f6-2a8e67608bc0","tags":[]},{"id":"poem-496e44b3ec8b3f49e235947b","title":"和严道培书院韵  其二","author":"米芾","dynasty":"宋","verses":["高馆搴帷万象开，西山翠入气佳哉。","六经重振南方学，千里还征上驾材。","鸾鹤遶庭翔更集，云霞拂栋去还来。","古今同被弦歌化，林卧其如老不才。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-922396cf-9325-4af0-bc81-704199610f77","tags":[]},{"id":"poem-49847e9f8b651b600df6ca4e","title":"定风波·自春来、惨绿愁红","author":"柳永","dynasty":"宋","verses":["自春来、惨绿愁红，芳心是事可可。","日上花梢，莺穿柳带，犹压香衾卧。","暖酥消，腻云。","终日厌厌倦梳裹。","无那。","恨薄情一去，音书无个。","早知恁么。","悔当初、不把雕鞍锁。","向鸡窗、只与蛮笺象管，拘束教吟课。","镇相随，莫抛躲。","针线闲拈伴伊坐。","和我。","免使年少，光阴虚过。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-146","tags":["宋词三百首"]},{"id":"poem-49852b1673b5c57452992676","title":"高轩过","author":"李贺","dynasty":"唐","verses":["华裾织翠青如葱，金环压辔摇玲珑。","马蹄隐耳声隆隆，入门下马气如虹。","云是东京才子，文章巨公。","二十八宿罗心胸，九精照耀贯当中。","殿前作赋声摩空，笔补造化天无功。","庞眉书客感秋蓬，谁知死草生华风。","我今垂翅附冥鸿，他日不羞蛇作龙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f4e6f5ab-ad75-4489-87f9-ffedbcc67926","tags":["叙事","写人","访友","赞颂","写人诗"]},{"id":"poem-4986d895f2a4bd46fb52a8dd","title":"菩萨蛮 其九","author":"温庭筠","dynasty":"唐","verses":["满宫明月梨花白，故人万里关山隔。","金雁一双飞，泪痕沾绣衣。","小园芳草绿，家住越溪曲。","杨柳色依依，燕归君不归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-8","tags":[]},{"id":"poem-498d1486c5fa5f3c285d555b","title":"贺新郎·梦冷黄金屋","author":"蒋捷","dynasty":"宋","verses":["梦冷黄金屋。","叹秦筝、斜鸿阵里，素弦尘扑。","化作娇莺飞归去，犹认纱窗旧绿。","正过雨、荆桃如菽。","此恨难平君知否，似琼台、涌起弹棋局。","消瘦影，嫌明烛。","鸳楼碎泻东西玉。","问芳、何时再展，翠钗难卜。","待把宫眉横云样，描上生绡画幅。","怕不是、新来妆束。","彩扇红牙今都在，恨无人、解听开元曲。","空掩袖，倚寒竹。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-255","tags":["宋词三百首"]},{"id":"poem-499007cce0d25509e98dd8e5","title":"广陵道","author":"赵嘏","dynasty":"唐","verses":["鬬鸡台边花照尘，炀帝陵下水含春。","青云回翅北归雁，白首哭途何处人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-dc71446e-1119-464f-a37a-070cad1ab353","tags":[]},{"id":"poem-4994183962cb6ae2a63a401d","title":"句","author":"孙逖","dynasty":"唐","verses":["野烟出炉上，山花落镜中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-618b91b5-13b0-415c-8402-0fa9ab341591","tags":[]},{"id":"poem-49967079b176d3ef81f35823","title":"二使者游东山酒后寄诗走笔次韵  其一","author":"张栻","dynasty":"宋","verses":["颇闻东山盛行乐，坐想风前酒兴豪。","领略正应胸次别，吟哦更觉笔端高。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-233d5b25-9f66-46ff-bd0d-e911434c770b","tags":[]},{"id":"poem-4999d8b9ec684f9c6883e667","title":"书倪氏屋壁三首 二","author":"贯休","dynasty":"唐","verses":["白桑红椹莺咽咽，面揉玉尘饼挑雪。","将为数日已一月，主人于我特地切。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-8e422260-dad4-4f42-8d01-eeb08e55baa3","tags":[]},{"id":"poem-49a01052db833b1b91c127ef","title":"紫苏丸","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["奴家年少正青春，占州城煞有声名。","把梨园格范尽番腾，当场敷演人钦敬。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-297","tags":[]},{"id":"poem-49a34383ca399896c695924e","title":"玉楼春·池塘水绿春微暖","author":"欧阳修","dynasty":"宋","verses":["池塘水绿春微暖。","记得玉真初见面。","从头歌韵响铮𫓩，入破舞腰红乱旋。","玉钩帘下香阶畔。","醉后不知红日晚。","当时共我赏花人，点检如今无一半。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-173","tags":["宋词三百首"]},{"id":"poem-49adaacc994540f333894fa7","title":"玄都坛歌寄元逸人","author":"杜甫","dynasty":"唐","verses":["故人昔隐东蒙峰，已佩含景苍精龙。","故人今居子午谷，独在阴崖结茅屋。","屋前太古玄都坛，青石漠漠常风寒。","子规夜啼山竹裂，王母昼下云旗翻。","知君此计成长往，芝草琅玕日应长。","铁鏁高垂不可攀，致身福地何萧爽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-bb6d1c12-1eb1-4ee7-aacd-a3f7f6edec37","tags":[]}];
